def replay_finish():
    if "dir" not in _REPLAY:
        return
    try:
        import gzip, shutil
        d, meta = _REPLAY["dir"], _REPLAY["meta"]
        with gzip.open(os.path.join(d, "http.jsonl.gz"), "wt", encoding="utf-8") as f:
            for row in _REPLAY["http"]:
                f.write(json.dumps(row, ensure_ascii=False) + "\n")
        os.makedirs(os.path.join(d, "outputs"), exist_ok=True)
        hist = os.path.join(KW_DIR, "history", f"{now():%Y-%m-%d}.json")
        for src in (hist, os.path.join(KW_DIR, "queue.md")):
            if os.path.exists(src):
                shutil.copy2(src, os.path.join(d, "outputs", os.path.basename(src)))
        meta.update(finished=True, finished_at=now().isoformat(), responses=len(_REPLAY["http"]),
                    withheld=_REPLAY.get("withheld", 0), history=os.path.basename(hist))
        json.dump(meta, io.open(os.path.join(d, "meta.json"), "w", encoding="utf-8"), ensure_ascii=False, indent=1)
        print(f"· 재생 기록 → {d} (응답 {len(_REPLAY['http'])}개)")
    except Exception as e:
        print(f"· 재생 기록 마무리 실패(run은 그대로): {type(e).__name__}: {e}")
    finally:
        _REPLAY.clear()

class Cache:
    """~/.cache/blog-kw/{name}.json — {key: [저장시각, 값]}"""
    def __init__(self, name, flush_every=40):
        os.makedirs(CACHE_DIR, exist_ok=True)
        self.path = os.path.join(CACHE_DIR, name + ".json")
        self.ttl = TTL[name] * 86400
        self.flush_every = flush_every
        try:
            self.d = json.load(io.open(self.path, encoding="utf-8"))
        except Exception:
            self.d = {}
        self.dirty = 0
    def get(self, k):
        v = self.d.get(k)
        return v[1] if v and _epoch() - v[0] < self.ttl else None
    def put(self, k, val):
        self.d[k] = [_epoch(), val]
        self.dirty += 1
        if self.dirty >= self.flush_every:
            self.save()
    def save(self):
        if self.dirty:
            json.dump(self.d, io.open(self.path, "w", encoding="utf-8"), ensure_ascii=False)
            self.dirty = 0

