def ac_naver(q):
    key = "n:" + q
    v = C_AC.get(key)
    if v is None:
        u = ("https://ac.search.naver.com/nx/ac?q=" + urllib.parse.quote(q)
             + "&con=1&frm=nv&ans=2&r_format=json&r_enc=UTF-8&st=100")
        try:
            v = [x[0] for x in json.loads(http(u)).get("items", [[]])[0]]
        except Exception:
            return []
        C_AC.put(key, v)
    return v

def ac_google(q):
    key = "g:" + q
    v = C_AC.get(key)
    if v is None:
        u = ("https://suggestqueries.google.com/complete/search?client=firefox&hl=ko&gl=kr&q="
             + urllib.parse.quote(q))
        try:
            v = json.loads(http(u))[1]
        except Exception:
            return []
        C_AC.put(key, v)
    return v

def verdict(q, sug):
    if not sug:
        return "없음"
    return "정확" if any(norm(x) == norm(q) for x in sug) else "근접"


