def load_keys():
    """Generated: no key is read. "Present" exactly when the recorded run had one, so the same branch runs; the Search
    Ad responses come from the recording."""
    return {"CUSTOMER_ID": "replay", "ACCESS_LICENSE": "replay", "SECRET_KEY": "replay", "_src": "replay"} if _HAS_VOL else None

def _cnt(v):
    if isinstance(v, (int, float)):
        return int(v)
    return 5 if "<" in str(v) else int(re.sub(r"\D", "", str(v)) or 0)   # "< 10" → 5

def searchad(hints, keys):
    """hints 최대 5개 → {정규화 키워드: {pc, mo, total, comp}} (연관 키워드 포함)"""
    uri, ts = "/keywordstool", str(int(_epoch() * 1000))
    sig = base64.b64encode(hmac.new(keys["SECRET_KEY"].encode(), f"{ts}.GET.{uri}".encode(), hashlib.sha256).digest()).decode()
    q = urllib.parse.urlencode({"hintKeywords": ",".join(re.sub(r"\s+", "", h) for h in hints), "showDetail": "1"})
    hdr = {"X-Timestamp": ts, "X-API-KEY": keys["ACCESS_LICENSE"], "X-Customer": str(keys["CUSTOMER_ID"]), "X-Signature": sig}
    data = json.loads(http("https://api.searchad.naver.com" + uri + "?" + q, headers=hdr, pause=0.35))
    out = {}
    for r in data.get("keywordList", []):
        pc, mo = _cnt(r.get("monthlyPcQcCnt")), _cnt(r.get("monthlyMobileQcCnt"))
        out[norm(r["relKeyword"])] = {"kw": r["relKeyword"], "pc": pc, "mo": mo, "total": pc + mo, "comp": r.get("compIdx", "")}
    return out

def volumes(kws, keys, related=None):
    """kws의 월 검색량. related(dict)를 주면 API가 돌려준 연관 키워드 전부를 거기 모은다."""
