ENTITY_SEED_INTENTS = {
    "ai_tool": ("요금제", "무료", "해지", "환불", "오류", "사용법", "결제", "비교"),
    "platform": ("광고비", "광고 설정", "정산", "수수료", "입점", "등록", "리뷰 관리", "사장님"),
}

def _entity_seed_name(name, match):
    """씨앗에 쓸 이름 — 레지스트리 이름에 한글이 있으면 그것, 아니면 match 열에서 한글이 든 평범한 대안(정규식 기호 없는 것), 없으면 레지스트리 이름."""
    if re.search(r"[가-힣]", name):
        return name
    for alt in match.split("|"):
        a = re.sub(r"\\s\?|\\s\*|\\s| \?", "", alt).strip()
        if re.search(r"[가-힣]", a) and re.fullmatch(r"[가-힣A-Za-z0-9 ]{2,20}", a):
            return a
    return name

def entity_seeds(path=None):
    """entities.tsv의 ai_tool·platform 행 × 의도어. 파일이 없거나 못 읽으면 [] — 사람 씨앗만으로 돈다(예전 동작)."""
    path = path or os.path.join(KW_DIR, "entities.tsv")
    out = []
    try:
        rows = [l.rstrip("\n").split("\t") for l in io.open(path, encoding="utf-8") if l.strip() and not l.startswith("#")]
    except OSError:
        return []
    for r in rows:
        if len(r) >= 3 and r[1] in ENTITY_SEED_INTENTS:
            name = _entity_seed_name(r[0].strip(), r[2].strip())
            out += [f"{name} {i}" for i in ENTITY_SEED_INTENTS[r[1]]]
    return out
