REJECT_DAYS = {"DUP": None, "UNVERIFIED": 30, "NO_REPRO": None, "THIN": 60, "UNSAFE": 3650, "OFF_LANE": 3650, "SOURCE_403": 30}
# 2026-10-19 Thomas: SOURCE_403 = 유일한 공식 출처가 서버 403이라 원고를 쓰지 못했다(브라우저 확인 전 — 탈락 판정이 아니다).
# 일부 주장만 403이면 지금처럼 hold 원고(browser_check)로 간다(1-C 출처). 원고도 거절 기록도 없던 후보가 매일 목록 1위로 돌아와
# 평가 칸을 먹었다(10-19 '제미 나이 캔바 사용법'). 사유에 그 URL을 적는다 — 브라우저로 확인할 주소다
FOREVER = "9999-12-31"
# 2026-10-25 Thomas('겹친 후보가 큐에 남지 않게'): 네이버 원고 작업 STEP 0이 버린 큐 후보도 기록한다 — 기록이 없어 같은 후보를 날마다 다시 평가했다
# (10-25 수동 실행 두 번: 보건증 조회·임대차신고·4대보험 가입증명서·포토샵 누끼·인스타 리포스트가 두 번 다 탈락). 코드는 티스토리와 같고 OOL(체급 밖)만 더한다.
# run이 until까지 큐에서 빼고, --max-age 재사용 중에도 큐에 거절된 후보가 있으면 큐를 새로 만든다(stale_candidates)
NAVER_REJECTS_F = os.path.join(KW_DIR, "naver_rejects.tsv")
NAVER_REJECT_DAYS = {**REJECT_DAYS, "OOL": 30}

# ───────────────────────── 미등록 용어 기록 (F1, 2026-10-20 Thomas 승인) ─────────────────────────
# 레인 판정(lane_of)이 못 잡아 버린 말을 기록만 한다 — 도구 목록(LANE_RE·entities.tsv)을 늘릴 근거(주간 도구 후보 표, F2).
# 전에는 dropped["레인 밖"] 숫자만 남아 무엇이 버려졌는지 알 수 없었다(10-20 검증: 새 도구 씨앗 확장 56개 중 32개가 레인 없음).
# 판정·큐·후보는 바꾸지 않는다. 기록이 실패해도 실행은 계속한다(관문이 아니라 관찰이다).
UNKNOWN_TERMS_F = os.path.join(KW_DIR, "unknown_terms.tsv")
UNKNOWN_KEEP_DAYS = 56
_UNKNOWN = collections.Counter()
_UNKNOWN_VOL = {}
_UNKNOWN_SHOW = {}

def note_unknown(kw, src, vol=None):
    """레인 밖으로 버린 말 하나 — 같은 실행 안에서는 (정규화한 말, 출처)로 센다."""
    kw = re.sub(r"\s+", " ", kw or "").strip()
    if not kw or "\t" in kw:
        return
    key = (norm(kw), src)
    _UNKNOWN[key] += 1
    _UNKNOWN_SHOW.setdefault(key, kw)
    if vol:
        _UNKNOWN_VOL[key] = vol

UNKNOWN_COLS = "term\tsource\tfirst\tlast\tdays\tcount\tvol"

def save_unknown_terms(day=None):
    """이번 실행에서 모은 말을 (말, 출처)마다 한 줄로 합친다 — first·last = 처음·마지막 잡힌 날, days = 잡힌 날 수,
    count·vol = 마지막 날 실행의 값. 같은 날 다시 돌면 days는 그대로 두고 count·vol만 바꾼다. last가 UNKNOWN_KEEP_DAYS일
    지난 줄은 지운다. 2026-10-23: 전에는 날마다 줄을 새로 덧붙여(날짜·말·출처·count·vol) 같은 말이 매일 다시 적혔다 —
    10-21~23 사흘 16,865줄 중 98%가 전날과 같은 말이었다(56일 보관이면 약 32만 줄). 옛 형식 파일은 읽을 때 합친다."""
    if not _UNKNOWN:
        return
    day = day or f"{now():%Y-%m-%d}"
    try:
        keep_from = (datetime.date.fromisoformat(day) - datetime.timedelta(days=UNKNOWN_KEEP_DAYS)).isoformat()
        acc = {}   # (정규화한 말, 출처) → [보이는 말, first, last, 날짜 집합 또는 days, count, vol]
        if os.path.exists(UNKNOWN_TERMS_F):
            lines = [l.rstrip("\n").split("\t") for l in io.open(UNKNOWN_TERMS_F, encoding="utf-8") if l.strip() and not l.startswith("#")]
            new_fmt = bool(lines) and "\t".join(lines[0]) == UNKNOWN_COLS
            for f in lines[1:] if lines and lines[0][0] in ("date", "term") else lines:
                if new_fmt and len(f) >= 7:
                    kw, src, first, last, days, cnt, vol = f[:7]
                    acc[(norm(kw), src)] = [kw, first, last, int(days or 1), cnt, vol]
                elif not new_fmt and len(f) >= 4:   # 옛 형식: date·term·source·count·vol (하루 한 줄)
                    d, kw, src, cnt = f[:4]
                    vol = f[4] if len(f) > 4 else ""
                    r = acc.setdefault((norm(kw), src), [kw, d, d, set(), cnt, vol])
                    r[3].add(d); r[1] = min(r[1], d)
                    if d >= r[2]:
                        r[0], r[2], r[4], r[5] = kw, d, cnt, vol or r[5]
        for r in acc.values():
            if isinstance(r[3], set):
                r[3] = len(r[3])
        for k, n in _UNKNOWN.items():
            vol = str(_UNKNOWN_VOL.get(k, ""))
            r = acc.get(k)
            if r is None:
                acc[k] = [_UNKNOWN_SHOW[k], day, day, 1, str(n), vol]
            else:
                if r[2] != day:
                    r[3] += 1
                r[0], r[2], r[4], r[5] = _UNKNOWN_SHOW[k], max(r[2], day), str(n), vol or r[5]
                r[1] = min(r[1], day)
        tmp = UNKNOWN_TERMS_F + ".tmp"
        with io.open(tmp, "w", encoding="utf-8") as f:
            f.write("# 레인 밖으로 버린 말(F1) — kw_pipeline.py run·tistory-refresh가 (말, 출처)마다 한 줄로 합친다. 도구 목록을 늘릴 근거(주간 도구 후보 표). 손으로 고치지 않는다\n")
            f.write(UNKNOWN_COLS + "\n")
            for (kw, first, last, days, cnt, vol), (_, src) in sorted(((r, k) for k, r in acc.items() if r[2] >= keep_from), key=lambda x: (x[1][1], x[0][0])):
                f.write("\t".join([kw, src, first, last, str(days), cnt, vol]) + "\n")
        os.replace(tmp, UNKNOWN_TERMS_F)
        _UNKNOWN.clear(); _UNKNOWN_VOL.clear(); _UNKNOWN_SHOW.clear()
    except Exception as e:
        print(f"· 미등록 용어 기록 실패(실행은 계속): {e}")

# ───────────────────────── 새 도구 후보 주간 표 (F2, 2026-10-23 Thomas 승인) ─────────────────────────
# unknown_terms.tsv(F1, 최근 14일)의 레인 밖 말을 머리 낱말(첫 낱말, 회사·플랫폼 이름이면 첫 두 낱말)로 묶어 '도구 이름 후보'를 고른다.
# 거르기: 말 2개 이상 또는 출처 2곳 이상 · 그 말들 중 도구 맥락(요금·사용법·해지·무료…) 비율 TOOL_CTX_MIN 이상(지명·날짜·뉴스 제목을 뺀다).
# 위 TOOL_TOP개만 네이버·구글 자동완성을 보고 동명이물 점검(자동완성 중 도구 맥락 비율)을 붙인다. 공식 도움말이 서버에서 읽히는지는
# 사람이 승인 전에 본다(자동 아님). 이미 아는 도구(entities.tsv)인데 레인 관문(LANE_RE)이 못 잡아 버린 말은 따로 적는다(F3의 실제 사례).
# 판정·큐·후보는 바꾸지 않는다 — 표만 만든다. Thomas가 '승인: 도구 추가 <이름> <패턴>'으로 고른다.
TOOL_CANDS_F = os.path.join(KW_DIR, "tool_candidates.md")
TOOL_WINDOW_DAYS = 14
TOOL_TOP = 15
TOOL_CTX_MIN = 0.3
F3_SINCE = "2026-10-24"   # F3(관문을 entities.tsv에서) 뒤 첫 root 실행일 — 이 날부터 마지막으로 버린 말만 'AI 관문 누락'으로 본다
TOOL_CTX = re.compile(r"ai|요금|가격|비용|사용법|쓰는 ?법|무료|유료|결제|구독|해지|환불|취소|앱|어플|프로그램|사이트|다운|설치|로그인|"
                      r"기능|툴|자막|편집|생성|번역|요약|변환|계정|플랜|플러스|가입|만들기|챗봇|한도|오류|대체|비교|차이|할인", re.I)

def _unknown_rows():
    if not os.path.exists(UNKNOWN_TERMS_F):
        return []
    lines = [l.rstrip("\n").split("\t") for l in io.open(UNKNOWN_TERMS_F, encoding="utf-8") if l.strip() and not l.startswith("#")]
    if not lines or "\t".join(lines[0]) != UNKNOWN_COLS:
        return []          # 옛 형식이면 다음 save_unknown_terms가 합친 뒤에 읽는다
    return [dict(term=f[0], src=f[1], first=f[2], last=f[3], days=int(f[4] or 1), vol=int(f[6]) if len(f) > 6 and f[6].isdigit() else 0)
            for f in lines[1:] if len(f) >= 6]

def tool_candidates(day=None, top=TOOL_TOP, net=True, write=True, log=print):
    """→ dict(rows=[...], alias=[...]). write면 analytics/keywords/tool_candidates.md를 새로 쓴다."""
    pass
    from . import kw_taxonomy as bt
    es = bt.load_entities()
    day = datetime.date.fromisoformat(day) if day else now().date()
    since = (day - datetime.timedelta(days=TOOL_WINDOW_DAYS)).isoformat()
    tool_ent = lambda s: [e["name"] for e in es if e["kind"] == "ai_tool" and e["rx"].search(s.lower())]
    plat_ent = lambda s: [e["name"] for e in es if e["kind"] in ("platform", "maker") and e["rx"].search(s.lower())]
    platform = collections.defaultdict(set)
    company = lambda s: any(e["kind"] == "company" and e["rx"].search(s.lower()) for e in es)
    agg, alias = {}, collections.defaultdict(set)
    for r in _unknown_rows():
        if r["last"] < since:
            continue
        toks = r["term"].split()
        if len(toks) < 2:
            continue
        ents = tool_ent(r["term"])
        if ents:            # 이미 아는 AI 도구인데 레인 관문이 못 잡았다 — F3 뒤에는 생기지 않아야 한다(entities.tsv에서 관문을 만든다)
            if r["last"] >= F3_SINCE:   # F3 전(10-21~23)에 버린 말은 이미 고친 사례라 적지 않는다
                alias[", ".join(ents)].add(r["term"])
            continue
        pents = plat_ent(r["term"])
        if pents:           # 플랫폼·제조사 이름이 있는 레인 밖 말 — 새 도구가 아니다. 레인을 넓힐지는 사람이 본다
            platform[", ".join(pents)].add(r["term"])
            continue
        head = toks[0] if not company(toks[0]) and len(toks) >= 2 else " ".join(toks[:2])
        if len(norm(head)) < 2 or re.fullmatch(r"[\d\W_]+", head) or TOOL_CTX.fullmatch(head) or lane_of(head) or lane_of(head + " 사용법"):
            continue
        a = agg.setdefault(norm(head), dict(head=head, terms=set(), src=set(), days=0, vol=0))
        a["terms"].add(r["term"]); a["src"].add(r["src"]); a["days"] = max(a["days"], r["days"]); a["vol"] = max(a["vol"], r["vol"])
    rows = []
    for a in agg.values():
        if len(a["terms"]) < 2 and len(a["src"]) < 2:
            continue
        ctx = sum(1 for t in a["terms"] if TOOL_CTX.search(t[len(a["head"]):])) / len(a["terms"])
        if ctx < TOOL_CTX_MIN:
            continue
        rows.append(dict(a, ctx=round(ctx, 2)))
    rows.sort(key=lambda a: (-len(a["src"]), -len(a["terms"]), -a["days"], -a["vol"]))
    rows = rows[:top * 2]      # 자동완성은 두 배까지 보고, 동명이물 점검을 통과한 것을 위 표로 올린다
    posts = own_posts()
    for a in rows:
        h = norm(a["head"])
        a["owned"] = sum(1 for p in posts if any(h in norm(k) for k in p["keywords"][:1]) or h in norm(p.get("title") or ""))
        a["nac"] = a["gac"] = None
        if net:
            n, g = ac_naver(a["head"]), ac_google(a["head"])
            sug = [x for x in n + g if norm(x) != h]
            a["nac"], a["gac"] = len(n), len(g)
            a["homonym"] = round(sum(1 for x in sug if TOOL_CTX.search(x)) / len(sug), 2) if sug else None
    strong = [a for a in rows if a.get("homonym") is None or a["homonym"] >= TOOL_CTX_MIN][:top]
    weak = [a for a in rows if a not in strong]
    rows = strong
    out = dict(rows=strong, weak=weak, alias=sorted(alias.items(), key=lambda x: -len(x[1])), platform=sorted(platform.items(), key=lambda x: -len(x[1])))
    if write:
        L = [f"# 새 도구 후보 (F2) — {day.isoformat()}", "",
             f"> `kw_pipeline.py tool-candidates`가 만든다(월요일 `run`이 자동으로). 손으로 고치지 않는다. 입력: `unknown_terms.tsv` 최근 {TOOL_WINDOW_DAYS}일의 레인 밖 말.",
             f"> 머리 낱말로 묶고, 말 2개 이상 또는 출처 2곳 이상, 그 말들 중 도구 맥락(요금·사용법·해지·무료 등) 비율 {TOOL_CTX_MIN} 이상만 남겼다. 위 {top}개까지.",
             "> **동명이물**은 머리 낱말 하나의 네이버·구글 자동완성 중 도구 맥락 비율이다. 낮으면(예: 0.3 미만) 한정어 패턴(`브루 ?ai|브루 자막`)을 요구한다.",
             "> **공식 도움말이 서버에서 읽히는지는 자동으로 보지 않는다** — 승인 전에 사람이 확인한다. 고르기: `승인: 도구 추가 <이름> <패턴>`.", "",
             "| # | 머리 낱말 | 출처 | 말 수 | 잡힌 날(최대) | 검색량(최대) | 말 속 도구 맥락 | 자동완성 네이버·구글 | 동명이물(맥락 비율) | 보유 글 | 예시 말 |",
             "|---|---|---|---|---|---|---|---|---|---|---|"]
        for i, a in enumerate(rows, 1):
            acs = "—" if a["nac"] is None else f"{a['nac']}·{a['gac']}"
            hom = "—" if a.get("homonym") is None else f"{a['homonym']:.2f}"
            ex = " · ".join(sorted(a["terms"], key=len)[:3])
            L.append(f"| {i} | **{a['head']}** | {len(a['src'])}곳({', '.join(sorted(a['src']))}) | {len(a['terms'])} | {a['days']} | {a['vol'] or '—'} | "
                     f"{a['ctx']:.2f} | {acs} | {hom} | {a['owned']} | {ex} |")
        if not rows:
            L.append("| — | 이번 주 후보 없음 | | | | | | | | | |")
        L += ["", f"### 참고 — 자동완성의 도구 맥락이 {TOOL_CTX_MIN} 미만(일반 말·기기·지명 등일 가능성)", ""]
        L += [f"- {a['head']} ({len(a['terms'])}개, 맥락 {a['homonym']:.2f}): " + " · ".join(sorted(a["terms"], key=len)[:3]) for a in weak[:10]] or ["- 없음"]
        L += ["", "## 이미 아는 AI 도구인데 레인 관문이 버린 말", "",
              "> F3(10-23)부터 AI 레인 관문은 `entities.tsv`의 ai_tool 행에서 만든다 — 여기 줄이 있으면 관문과 분류가 다시 어긋났다는 뜻이다(10-23 이전 기록 제외).", ""]
        L += [f"- **{name}** — {len(ts)}개: " + " · ".join(sorted(ts, key=len)[:5]) for name, ts in out["alias"]] or ["- 없음"]
        L += ["", "## 플랫폼·제조사 이름이 있는 레인 밖 말 (참고)", "",
              "> 새 도구가 아니다. 마케팅 레인 관문은 코드에 있다 — 넓힐지는 사람이 본다(대개 사장님 의도가 아닌 일반 사용자 검색).", ""]
        L += [f"- {name} — {len(ts)}개: " + " · ".join(sorted(ts, key=len)[:5]) for name, ts in out["platform"]] or ["- 없음"]
        with io.open(TOOL_CANDS_F, "w", encoding="utf-8") as f:
            f.write("\n".join(L) + "\n")
        log(f"· 새 도구 후보 {len(rows)}개 · AI 관문 누락 {len(out['alias'])}개 · 플랫폼 말 {len(out['platform'])}묶음 → {TOOL_CANDS_F}")
    return out


def tistory_candidates(cands, posts, keys, log=print):
    pool = {}
    for c in cands:   # 네이버 큐 발굴분 중 구글 자동완성에서 온 AI 도구 말
        if c.get("goo") and lane_of(c["kw"]) == "AI 활용":
            pool.setdefault(norm(c["kw"]), c["kw"])
    # 네이버 큐에 있는 마케팅·실무 후보는 티스토리가 가져가지 않는다 — 티스토리에 쓰면 own_posts가 그 말을 '보유'로 보고 네이버 큐에서 빠진다
    naver_q = {norm(c["kw"]) for c in cands if lane_of(c["kw"]) not in (None, "AI 활용")}
    tposts = [p for p in posts if p.get("platform") == "tistory"]
    nposts = [p for p in posts if p.get("platform") == "naver"]
    seeds = [l.strip() for l in io.open(SEEDS_TISTORY_F, encoding="utf-8")
             if l.strip() and not l.startswith("#")] if os.path.exists(SEEDS_TISTORY_F) else []
    have = {norm(s) for s in seeds}
    extra = [s for s in entity_seeds() if norm(s) not in have]
    log(f"· 티스토리 전용 씨앗어 {len(seeds)}개 + 레지스트리 씨앗 {len(extra)}개 구글 자동완성 확장")
    seeds += extra
    for s in seeds:
        pool.setdefault(norm(s), s)
        for x in ac_google(s):
            pool.setdefault(norm(x), x)
    out = []
    for kw in pool.values():
        kw = re.sub(r"\s+", " ", kw).strip()
        lane = lane_of(kw)
        if not lane:
            note_unknown(kw, "티스토리")   # F1
        if not 3 <= len(norm(kw)) <= 22 or lane not in TISTORY_LANES or not (TISTORY_INTENT if lane == "AI 활용" else PRACTICE_INTENT).search(kw):
            continue
        if lane != "AI 활용" and norm(kw) in naver_q:
            continue
        if norm(kw) in HEAD_TERMS or OFFTOPIC.search(kw) or SIDEHUSTLE.search(kw) or PRODUCT.search(kw) or TOOLBOX.search(kw):
            continue
        if NAVI.search(kw) and not TISTORY_BREAK.search(kw):   # '클로드 로그인'은 접속, '클로드 로그인 오류'는 글감
            continue
        if TISTORY_UNSAFE.search(kw):
            continue
        if covered_by(kw, tposts):
            continue
        # 2026-10-10 (Thomas): 키워드가 같아도 다루는 질문·결론이 다르면 다른 글이다. 네이버만 다룬 키워드는 버리지 않고 2순위로 —
        # 쓸 때 그 네이버 글과 다른 질문·결론(angle)을 밝히고 링크해야 한다(1-C). 티스토리에 이미 있으면 위에서 뺐다
        nc = covered_by(kw, nposts)
        out.append({"kw": kw, "lane": lane, "intent": "티스토리", "src": ["티스토리"], "naver_covered": nc[0] if nc else ""})
    if keys and out:
        vol = volumes([c["kw"] for c in out], keys)
        for c in out:
            c["vol"] = vol.get(norm(c["kw"]))
    for c in out:
        c["goo_v"] = verdict(c["kw"], ac_google(c["kw"]))
    out = [c for c in out if c["goo_v"] == "정확"]   # 구글 제안에 없는 말은 티스토리 제목 키워드로 못 건다(1-A)
    out.sort(key=lambda c: -((c.get("vol") or {}).get("total", 0)))
    # '클로드 환불'·'클로드 환불 방법'·'클로드 환불 요청'은 한 편 주제다. 보유 판정(covered_by)과 같은 규칙으로 묶어
    # 검색량 큰 말 하나만 남긴다 — 하루 12개뿐인 구글 측정 몫을 같은 주제에 쓰지 않게(2026-10-03)
    kept = []
    for c in out:
        if not covered_by(c["kw"], [{"file": "", "keywords": [k["kw"] for k in kept], "google_kw": "", "tags": []}]):
            kept.append(c)
    out = kept
    save_caches()
    log(f"· 티스토리 전용 후보 {len(out)}개")
    return out

def tistory_rejects(today=None, path=None):
    """{norm(키워드): 행} — 기한(until)이 오늘 이후인 거절만. 같은 키워드는 마지막 줄이 이긴다."""
    today = today or now().date().isoformat()
    path = path or TISTORY_REJECTS_F
    out = {}
    if os.path.exists(path):
        for l in io.open(path, encoding="utf-8"):
            f = l.rstrip("\n").split("\t")
            if len(f) < 5 or l.startswith("#") or f[0] == "date":
                continue
            out[norm(f[1])] = {"date": f[0], "kw": f[1], "code": f[2], "detail": f[3], "until": f[4], "source": f[5] if len(f) > 5 else "ops"}
    return {k: r for k, r in out.items() if r["until"] >= today}

def naver_rejects(today=None):
    return tistory_rejects(today, NAVER_REJECTS_F)

def naver_reject(args):
    """kw_pipeline.py naver-reject "키워드" 코드 "사유" [--days N] — 네이버 원고 작업 STEP 0이 버린 큐 후보(2026-10-25)."""
    return tistory_reject(args, path=NAVER_REJECTS_F, codes=NAVER_REJECT_DAYS, cmd="naver-reject",
                          header="# 네이버 큐 후보 거절 기록 — kw_pipeline.py naver-reject 로만 쓴다. run이 until까지 큐에서 뺀다(Thomas 10-25)\n")

def tistory_reject(args, path=None, codes=None, cmd="tistory-reject", header=None):
    """kw_pipeline.py tistory-reject "키워드" 코드 "사유" [--days N] — 원고 작업이 버린 후보를 기록한다(형식을 고정하려고 명령으로만 쓴다)."""
    path, codes = path or TISTORY_REJECTS_F, codes or REJECT_DAYS
    header = header or "# 티스토리 전용 후보 거절 기록 — kw_pipeline.py tistory-reject 로만 쓴다. tistory-pick이 until까지 건너뛴다(Thomas 10-10 P3)\n"
    if len(args) < 3 or (args[1] not in codes and args[1] != "CLEAR"):
        sys.exit(f"사용: {cmd} \"키워드\" {{" + "|".join(codes) + "|CLEAR} \"사유(DUP면 같은 질문·결론인 글 파일명, CLEAR면 바뀐 질문·결론)\" [--days N] [--source ops|test]\n"
                 "서버 403은 거절이 아니다 — 원고를 status: hold · browser_check: 대기로 두고 브라우저로 확인한다(1-D)")
    kw, code, detail = args[0].strip(), args[1], re.sub(r"[\t\n]+", " ", args[2]).strip()
    if code == "SOURCE_403" and not re.search(r"https?://\S+", detail):
        sys.exit("SOURCE_403 사유에는 403이 난 공식 출처 URL을 적는다(브라우저로 확인할 주소)")
    if re.search(r"\b403\b", detail) and code not in ("UNVERIFIED", "SOURCE_403"):
        sys.exit("서버 403만으로는 거절하지 않는다 — 다른 주장은 확인되면 원고를 hold(브라우저 확인)로 쓴다. 유일한 공식 출처가 403이라 원고를 못 쓰면 "
                 "SOURCE_403(사유에 URL), 브라우저로도 확인이 안 됐을 때만 UNVERIFIED")
    d = now().date()
    src = args[args.index("--source") + 1] if "--source" in args else "ops"
    if code == "CLEAR":   # 질문·결론이 실질적으로 바뀌었을 때만 — 기한을 어제로 적어 마지막 줄이 이 거절을 끝낸다
        until = (d - datetime.timedelta(days=1)).isoformat()
    else:
        days = int(args[args.index("--days") + 1]) if "--days" in args else codes[code]
        until = FOREVER if days is None else (d + datetime.timedelta(days=days)).isoformat()
    new = not os.path.exists(path)
    with io.open(path, "a", encoding="utf-8") as f:
        if new:
            f.write(header)
            f.write("date\tkw\tcode\tdetail\tuntil\tsource\n")
        f.write(f"{d.isoformat()}\t{kw}\t{code}\t{detail}\t{until}\t{src}\n")
    print(f"기록: {kw} · {code} · " + ("거절을 끝냈다(다시 후보)" if code == "CLEAR" else "질문·결론이 바뀌기 전까지(CLEAR로만 푼다)" if until == FOREVER else f"{until}까지 뺀 뒤 다시 평가") + f" · 출처 {src}")

def tistory_cands_latest():
    """마지막 후보 목록 — tistory-refresh 파일과 마지막 run 스냅샷 중 새것. 2026-10-03 이전 스냅샷에는 tistory 키가 없다.
    2026-10-20: 새것은 파일 안 날짜로 정한다(refresh 파일의 date, 스냅샷 파일 이름). 파일 mtime은 clone·cp·git archive가 다시 찍는다 —
    C6b로 claude 계정에 새로 clone한 볼트에서 10-10 refresh 파일(149개)이 10-19 스냅샷(152개)보다 몇 ms 늦게 찍혀 낡은 목록이 뽑혔다.
    같은 날이면(날짜만으로 못 가르면) 그때만 mtime으로 가른다."""
    best, best_d, best_t = [], "", -1.0
    if os.path.exists(TISTORY_CANDS_F):
        try:
            j = json.load(io.open(TISTORY_CANDS_F, encoding="utf-8"))
            best, best_d, best_t = j.get("tistory", []), str(j.get("date", ""))[:10], os.path.getmtime(TISTORY_CANDS_F)
        except Exception:
            best, best_d, best_t = [], "", -1.0
    for h in reversed(sorted(glob.glob(os.path.join(KW_DIR, "history", "*.json")))):
        try:
            cands = json.load(io.open(h, encoding="utf-8")).get("tistory", [])
        except Exception:
            cands = []
        if cands:
            hd = os.path.basename(h)[:10]
            if hd > best_d or (hd == best_d and os.path.getmtime(h) > best_t):
                best = cands
            break
    return best

def tistory_refresh(args):
    """kw_pipeline.py tistory-refresh — run 없이 티스토리 전용 후보만 새로 모은다(씨앗 자동완성·검색량). queue.md·history는 건드리지 않는다."""
    hist = sorted(glob.glob(os.path.join(KW_DIR, "history", "*.json")))
    cands = []
    if hist:
        try:
            cands = json.load(io.open(hist[-1], encoding="utf-8")).get("candidates", [])
        except Exception:
            cands = []
    # history에는 run이 추린 후보만 남는다(run은 발굴 전체를 넘긴다). 직전 티스토리 후보(AI)를 다시 넣어 목록이 줄지 않게 한다
    prev = []
    for h in reversed(hist):   # 마지막 run 스냅샷의 티스토리 후보 + 직전 tistory-refresh 결과(합집합)
        try:
            prev = json.load(io.open(h, encoding="utf-8")).get("tistory", [])
        except Exception:
            prev = []
        if prev:
            break
    if os.path.exists(TISTORY_CANDS_F):
        try:
            prev = prev + json.load(io.open(TISTORY_CANDS_F, encoding="utf-8")).get("tistory", [])
        except Exception:
            pass
    cands = cands + [{"kw": c["kw"], "goo": True} for c in prev if c.get("lane", "AI 활용") == "AI 활용"]
    out = tistory_candidates(cands, own_posts(), load_keys())
    save_unknown_terms()   # F1
    with io.open(TISTORY_CANDS_F, "w", encoding="utf-8") as f:
        json.dump({"date": f"{now():%Y-%m-%d %H:%M}", "tistory": [{k: (sorted(v) if isinstance(v, set) else v) for k, v in c.items()} for c in out]}, f, ensure_ascii=False, indent=1)
    print(f"→ {os.path.relpath(TISTORY_CANDS_F, VAULT)} ({len(out)}개, 레인별 {dict(collections.Counter(c.get('lane', 'AI 활용') for c in out))})")

def tistory_pick(n=5, as_json=False):
    """원고 작업(blog-daily-draft 5 b-0)이 지금 쓸 티스토리 전용 주제. queue.md의 절은 큐를 만든 날의 측정값이라
    run --max-age 7이 큐를 재사용하는 동안 맥이 새로 잰 '자리 있음'이 안 보인다 — 그래서 마지막 후보 목록에
    지금의 google_slots.tsv와 지금의 볼트 원고(보유 여부)를 다시 대 본다.
    2026-10-10 (Thomas P3·P5): 거절 기록(tistory_rejects.tsv)의 기한 안 키워드는 뺀다. 레인을 AI 밖으로 넓혔다 —
    순서는 ① 새 키워드(측정·추정 '자리 있음') ② 네이버만 다룬 키워드(다른 질문·결론일 때만) ③ 실무 레인처럼 구글 자리 '없음'이 추정일 뿐인 키워드
    (다음 검색용, 측정으로 '없음'이 나온 말은 뺀다). 원고 작업은 이 목록을 위에서부터 평가하고, 한 후보가 탈락해도 다음 후보로 간다(1-D)."""
    cands = tistory_cands_latest()
    tiers, cnt = _tistory_tiers(cands, own_posts())
    tiers = {k: [{x: y for x, y in c.items() if x not in ("tier", "slot_v", "slot_guess")} for c in v] for k, v in tiers.items()}
    # 2026-10-10 시험 실행: 1순위 위 12개가 전부 AI 도구라 레인을 나눌 수 없었고, 실측·화면 확인이 필요한 후보가 몰려 8개 중 2편만 나왔다 →
    # 1순위 안에서 레인을 번갈아 세운다(레인 안의 순서는 그대로). 2·3순위는 그대로
    by_lane = collections.OrderedDict()
    for c in tiers[1]:
        by_lane.setdefault(c["lane"], []).append(c)
    rr = []
    while any(by_lane.values()):
        for lane in list(by_lane):
            if by_lane[lane]:
                rr.append(by_lane[lane].pop(0))
    tiers[1] = rr
    picks = tiers[1] + tiers[2] + tiers[3]
    head = (f"# 티스토리 전용 후보 {len(cands)}개 — 1순위 {len(tiers[1])} · 2순위(네이버만 다룸) {len(tiers[2])} · 3순위(구글 자리 추정 없음) {len(tiers[3])} · "
            + " · ".join(f"{k} {v}" for k, v in cnt.items()))
    if as_json:
        print(json.dumps({"summary": head, "picks": picks[:n]}, ensure_ascii=False))
        return
    print(head)
    for c in picks[:n]:
        tier = 1 if c in tiers[1] else 2 if c in tiers[2] else 3
        note = f"네이버 {os.path.basename(c['naver_covered'])[:24]}와 다른 질문·결론 필요" if c["naver_covered"] else "-"
        print(f"{tier}순위\t{c['kw']}\t{c['lane']}\t월 {(c.get('vol') or {}).get('total', 0):,}회\t{c['slot']}\t{form_hint(c['kw']) or '-'}\t{note}")
    if not picks:
        print("(쓸 후보 없음 — 오늘 티스토리는 0편)")

# 2026-10-23 D1(Thomas 승인): 같은 의도의 꾸밈말 변형 — 무료·엑셀·word·양식·방법·연도 같은 말을 빼고 남은 말이 기존 티스토리 글의 메인 키워드나
# DUP 거절 키워드와 같으면 평가하지 않는다. 거절 기록은 키워드 하나만 막아 '근로계약서 양식 무료·엑셀·word'가 10-21~23 사흘 동안 105편과 같은
# 질문으로 평가 칸 셋을 먹었다. 10-10 뒤 기록으로 잰 값: 10-21~23 DUP 11건 중 5건을 미리 거르고, 10-10 뒤 쓴 티스토리 전용 글 43편 중 걸리는 글 0.
TISTORY_DUP_MOD = re.compile(r"20\d\d년?|무료|엑셀|excel|word|워드|hwp|한글|pdf|다운로드|다운|양식|서식|방법|하는\s*법|받는\s*법|쓰는\s*법")

def tistory_dup_head(kw):
    """꾸밈말을 뺀 머리말(공백 없음, 소문자). 3자 미만이면 '' — 너무 짧은 머리말로는 같은 의도라고 보지 않는다."""
    h = re.sub(r"\s+", "", TISTORY_DUP_MOD.sub(" ", re.sub(r"([홈손])텍스", r"\1택스", (kw or "").lower())))   # 오타 표기 홈텍스·손텍스
    return h if len(h) >= 3 else ""

def _tistory_tiers(cands, posts):
    """tistory-pick의 거르기와 순위 나누기(정본) — ({1: [...], 2: [...], 3: [...]}, 뺀 사유 집계). 순위 안 순서는 후보 목록 순서 그대로.
    그림자 순위(tistory_rank)도 이것을 거친다 — 거르기 규칙은 여기 하나다."""
    tposts = [p for p in posts if p["platform"] == "tistory"]
    nposts = [p for p in posts if p["platform"] == "naver"]
    rej = tistory_rejects()
    heads = {tistory_dup_head(p["keywords"][0]) for p in tposts if p.get("keywords")} | {tistory_dup_head(r["kw"]) for r in rej.values() if r["code"] == "DUP"}
    heads.discard("")
    tiers = {1: [], 2: [], 3: []}
    cnt = collections.Counter()
    for c in cands:
        if covered_by(c["kw"], tposts):
            cnt["이미 씀"] += 1
            continue
        if norm(c["kw"]) in rej:
            code = rej[norm(c["kw"])]["code"]
            cnt["출처 403 대기" if code == "SOURCE_403" else "거절 " + ("같은 의도" if code == "DUP" else "재현 불가" if code == "NO_REPRO" else "재검증 대기" if code == "UNVERIFIED" else "기타")] += 1
            continue
        if tistory_dup_head(c["kw"]) in heads:   # D1
            cnt["같은 의도 변형(꾸밈말만 다름)"] += 1
            continue
        if TISTORY_UNSAFE.search(c["kw"]):
            cnt["쓰지 않는 말"] += 1
            continue
        v, guess = slot_judge(c["kw"])
        if v == "없음" and not guess:
            cnt["자리 없음(측정)"] += 1
            continue
        if v == "미측정":
            cnt["측정 대기"] += 1
            if c.get("lane", "AI 활용") == "AI 활용":   # 예전 규칙 그대로 — AI 미측정은 기다린다
                continue
        nc = covered_by(c["kw"], nposts)
        c = dict(c, lane=c.get("lane", "AI 활용"), naver_covered=nc[0] if nc else "", slot=slot_txt(c["kw"]))
        tier = 3 if v == "없음" else (2 if nc else 1)
        tiers[tier].append(dict(c, tier=tier, slot_v=v, slot_guess=guess))
    return tiers, cnt


# ───────────────────────── 티스토리 Slot C — 그림자 순위 (2026-10-10) ─────────────────────────
# 네이버 Slot C(select_slot_c)의 판정·점수 틀을 티스토리에 맞게 옮긴 것. 그림자 전용 — tistory-pick 기본 출력(cron이 읽는 목록)은
# 바꾸지 않는다(Thomas 10-10: 티스토리 1단계 운영 검증 10-11~10-13 동안 cron 조건 고정). 네이버와 다른 점:
#  · 기존 글 = 티스토리 원고(볼트 status가 정본 — 맥 루틴이 예약·발행을 적는다). 프론트매터에 cluster가 없으면 메모리에서만 분류한다
#  · 수요 = 구글 자리(측정 > 추정) + 네이버 검색량(약한 대리 지표). 네이버 큐 수요 가중치(.6)를 쓰지 않는다
#  · 미분류(unresolved)도 고를 수 있다 — 감점하고 확장 후보로 남긴다(티스토리 후보의 24%가 캡컷·코파일럿 같은 도구 전체 미분류)
#  · 재현 위험 감점 — 10-09~10 거절 11건 중 6건이 NO_REPRO(오류 재현·화면 확인 불가)였다
#  · 다양성 = 같은 날 티스토리 묶음(같은 도구·같은 질문 갈래는 같은 날 금지 — 1-C) + 최근 14일 티스토리 글. 그날 네이버 원고는 약한 감점만
#  · 네이버 판정이 같은 질문이면(covered_by가 못 잡은 것) 감점 — 쓸 때 다른 질문·결론(angle)을 세워야 해 탈락 위험이 크다
# 거르기(이미 씀·거절 기록·쓰지 않는 말·구글 자리 측정 없음)와 1·2·3순위는 _tistory_tiers 그대로다. 순위 사이 순서도 지킨다(1 → 2 → 3).
TSLOT_W = dict(base=0.6, slot={"측정": 0.4, "추정": 0.2}, demand={"CONFIRMED": 0.3, "WEAK": 0.1, "UNKNOWN": 0.0},
               status={"ACTIVE": 0.2, "CANDIDATE": 0.1}, gap=0.4, new_cluster=0.2, link=0.3, safe=0.2,
               repro=-0.4, naver_same=-0.3, overlap_medium=-0.4, overlap_low=-0.2, unresolved=-0.3, low_conf=-0.3,
               day_cluster=-0.3, day_lane=-0.15, recent_cluster=-0.15, recent_entity=-0.3, naver_today=-0.1, source_hold=-0.8,
               expired=-0.2, upcoming_confirmed=0.1, dup_family=-0.4, dup_family_repeat=-0.8, limit=-0.5)
# 2026-10-20 S2(Thomas 승인, 그림자만): 거절 기록의 DUP 키워드와 같은 도구 × 같은 질문 유형(tistory_qtype)이면 감점한다 — 제외가 아니다.
# 거절 기록은 키워드 하나만 막아 '챗gpt 해지하기'·'챗gpt 자동결제 해지'처럼 같은 질문의 변형이 매일 평가 칸을 먹었다(10-11~20 DUP 32건 중 20건이 글 4편에 몰림).
# 그날 전 거절만으로 사후 대조: DUP 16/32를 앞당겨 잡고 실제 작성된 비수동 글 감점 0편(analytics/tistory-후보공급-분석-2026-10-20.md)
TSLOT_RECENT_DAYS = 14
TSLOT_DAY = 3        # 하루 티스토리 전용 글 상한(1-C)
# 1-C '같은 날 가능하면 AI 1 · 마케팅/매장 1 · 실무 1': 아직 안 쓴 레인에 이 점수 이상인 후보가 있으면 그 레인에서 먼저 고른다(같은 단계 안에서만 —
# 3순위 실무는 1·2순위로 못 채운 날에만이라는 규칙은 그대로). 가중치만으로는 마케팅 후보(구글 미측정·미분류·검색량 작음)가 AI에 늘 밀렸다(10-10 시뮬레이션)
TSLOT_LANE_FLOOR = 0.5
TSLOT_MIN = 0.5      # 하루 묶음에 넣을 최저 점수 — 못 넘으면 그 칸은 비운다(1-C: 0편도 된다). 묶음 밖 차례(탈락 뒤 넘어갈 목록)에는 그대로 남는다
