TISTORY_SOURCE_HOLD = re.compile(r"챗 ?gpt|chatgpt|\bgpt|오픈 ?ai|openai|캔바|canva|미리 ?캔버스|miricanvas|감마|gamma", re.I)
# P-A: 공식 문서가 숫자를 싣지 않는 한도 질문 — 루프 라운드 1 NO_REPRO 5건 중 4건(클로드 무료·프로 한도, 제미나이 무료 한도 3)
TISTORY_LIMIT = re.compile(r"한도|횟수|제한")
