# F3(Thomas 2026-10-23 승인): AI 레인 관문의 도구 이름은 entities.tsv의 ai_tool 행(match 열)에서 만든다 — 승인된 행 하나가 관문과
# 분류(blog_taxonomy)를 함께 바꾼다. 전에는 두 목록이 따로라 분류는 '노트북 ?lm'·'챗지피티'·'canva'를 알아보는데 관문은 못 잡아
# 레인 밖으로 버렸다(F2 첫 표 10-23: NotebookLM 5·ChatGPT 1·캔바 1). 키워드 6,905개로 잰 변화: 레인 밖 → AI 활용 14개, 레인 이동·이탈 0.
# 도구가 아닌 AI 낱말만 코드에 둔다. entities.tsv를 못 읽으면 예전 목록으로(관문이 넓어지지 않는 쪽) — 경고를 한 번 찍는다.
AI_LANE_GENERIC = r"gpt|\bai\b|ai |인공지능|프롬프트|누끼"
AI_LANE_FALLBACK = r"챗\s?gpt|제미나이|gemini|클로드|claude|그록|코파일럿|퍼플렉시티|뤼튼|노트북lm|클로바노트|캔바|미리캔버스|망고보드|캡컷"
_AI_LANE = {}

def _ai_lane_re():
    if "rx" not in _AI_LANE:
        try:
            pass
            from . import kw_taxonomy as bt
            tools = [e["rx"].pattern for e in bt.load_entities() if e["kind"] == "ai_tool"]
            if not tools:
                raise ValueError("ai_tool 행 없음")
            _AI_LANE.update(rx=re.compile(AI_LANE_GENERIC + "|" + "|".join(f"(?:{t})" for t in tools), re.I), src="entities.tsv", n=len(tools))
        except Exception as e:
            print(f"· AI 레인 관문: entities.tsv를 못 읽어 예전 목록으로({type(e).__name__}: {e})", file=sys.stderr)
            _AI_LANE.update(rx=re.compile(AI_LANE_GENERIC + "|" + AI_LANE_FALLBACK, re.I), src="fallback", n=0)
    return _AI_LANE["rx"]

def lane_of(kw, default=None):
    for name, pat in LANE_RE:
        if (pat or _ai_lane_re()).search(kw):
            return name
    return default

