# 네이버 큐의 form_hint는 바꾸지 않는다.
TISTORY_MEASURE = re.compile(r"비교|vs|추천|순위|품질|속도|성능|후기|직접 ?써", re.I)
# AI 도구로 무언가를 만들어 보이는 질문(만들기·제작·생성·편집·변환)도 실측이다 — 결과물을 보여야 답이 된다. 10-11 P2의 예가 'ai 상세페이지 제작 무료'였고,
# 거절 NO_REPRO의 이미지·영상 생성 3건도 이것이다. AI 레인에서만 본다('인스타그램 비즈니스 계정 만들기'는 절차형).
TISTORY_MEASURE_AI_TASK = re.compile(r"만들기|만드는|제작|생성|편집|변환|그리기|그림")

def tistory_form_hint(kw):
    h = form_hint(kw)
    if h != "실측형" or TISTORY_MEASURE.search(kw) or (lane_of(kw) == "AI 활용" and TISTORY_MEASURE_AI_TASK.search(kw)):
        return h
    for name, pat in FORM_HINT:
        if name != "실측형" and re.search(pat, kw, re.I):
            return name
    return "판정형"

def form_hint(kw):
    if lane_of(kw) == "장비":   # 제휴 글은 써 보지 않은 물건의 실측을 지어낼 수 없다 → 사양·조건 판정 아니면 비용 계산
        return "계산형" if re.search(r"가격|비용|얼마|전기세|전기 ?요금|렌탈|임대|월 ?요금", kw) else "판정형"
    for name, pat in FORM_HINT:
        if re.search(pat, kw, re.I):
            return name
    return ""


