# 2026-10-05 Thomas: 제휴 후보가 얇아지면 seeds.txt [장비-예비]에서 씨앗을 꺼내 쓴다(update_stock). 예비는 씨앗으로 바로 읽지 않는다
RESERVE_LANE = "장비-예비"
EQUIP_GROUP_CAP = 6    # 큐의 장비 칸에서 한 묶음이 차지할 수 있는 후보 수(run의 per_lane)
STORY_GROUPS_MIN = 4   # 대기 '묶음'(같은 AI 이야기 = 글 한 편 감)이 이보다 적으면 예비 씨앗을 올린다
RESERVE_STEP = 3       # 한 번에 올리는 예비 씨앗 수

def read_reserve():
    lane, out = None, []
    for line in io.open(os.path.join(KW_DIR, "seeds.txt"), encoding="utf-8"):
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        m = re.match(r"\[(.+)\]", line)
        if m:
            lane = m.group(1)
        elif lane == RESERVE_LANE:
            out.append(line)
    return out

def read_tsv(name):
    p = os.path.join(KW_DIR, name)
    if not os.path.exists(p):
        return []
    return [l.rstrip("\n").split("\t") for l in io.open(p, encoding="utf-8") if l.strip() and not l.startswith("#")]

# 2026-10-25 Thomas 'CLICK_SHARE 보정': 주간 검색 대비 유입(capture.tsv = 이 주 유입 ÷ (월 검색량 ÷ 4.3))의 중앙값을 쓴다.
# 10-04·10-11·10-18 3주 44줄 중앙값 2.7%(주별 1.5·3.1·3.4%) — 가정 5%의 절반. 모든 후보에 같은 배수라 큐 순서는 바뀌지 않고,
# '점수'가 실측 기준의 예상 월 유입이 된다. 표본은 '이미 유입이 있는 검색어'라 위로 치우친 값이다(상한 쪽 추정).
CLICK_SHARE_MIN_ROWS, CLICK_SHARE_MIN_WEEKS = 30, 3

def measured_click_share():
    rows = [r for r in read_tsv("capture.tsv") if len(r) > 5 and r[5]]
    weeks = {r[0] for r in rows}
    if len(rows) < CLICK_SHARE_MIN_ROWS or len(weeks) < CLICK_SHARE_MIN_WEEKS:
        return CLICK_SHARE_DEFAULT, f"가정 {CLICK_SHARE_DEFAULT * 100:g}% (capture.tsv 실측 {len(rows)}줄·{len(weeks)}주 — {CLICK_SHARE_MIN_ROWS}줄·{CLICK_SHARE_MIN_WEEKS}주부터 실측)"
    v = clamp(statistics.median(float(r[5]) for r in rows), 0.005, 0.10)
    return v, f"실측 중앙값 {v * 100:.1f}% (capture.tsv {len(rows)}줄·{len(weeks)}주, 가정 {CLICK_SHARE_DEFAULT * 100:g}%)"

# 2026-10-25 Thomas '다음 편 후보 이어 붙이기': 주간 분석('해석과 결정'의 다음 편 주제)이 정체까지 확인한 후보를 원고 작업에 넘긴다.
# 10-18 주 후보 4개 중 2개(4대보험 가입자명부 발급·네이버 블로그 2개 만들기)가 큐 점수가 낮아(API 하한) 한 주 동안 안 쓰였다.
# 형식: 주말일\t키워드\t근거 한 줄[\t레인[\t닫은 사유]]. 주간 보고가 덧붙이고, STEP 0이 버리면 `next-topics --close 키워드 사유`가 닫은 줄을 덧붙인다. 같은 키워드는 뒤 줄이 이긴다.
# 그 주 뒤에 새로 쓴 네이버 원고가 다루면(covered_by) 닫히고, NEXT_TOPICS_DAYS가 지나면 내린다(주간 보고가 다시 적으면 살아난다).
NEXT_TOPICS_DAYS = 28

def next_topics(posts=None, today=None):
    posts = own_posts() if posts is None else posts
    today = today or now().date()
    by = {}
    for r in read_tsv("next_topics.tsv"):
        if len(r) < 2 or not r[1].strip():
            continue
        try:
            age = (today - datetime.date.fromisoformat(r[0].strip())).days
        except ValueError:
            continue
        kw = r[1].strip()
        by[norm(kw)] = {"date": r[0].strip(), "kw": kw, "why": r[2].strip() if len(r) > 2 else "",
                        "lane": (r[3].strip() if len(r) > 3 else "") or lane_of(kw), "age": age,
                        "closed": r[4].strip() if len(r) > 4 else ""}
    out = []
    for c in by.values():
        # 닫힘은 '그 주 뒤에 새로 쓴 네이버 원고'가 다룰 때만 — 주간 분석은 기존 글(71편 같은 모검색어 글·티스토리 /48)을 보고도
        # 하위 의도를 새 글로 고른 것이라, 옛 글로 닫으면 안 된다(10-25 첫 시험: 둘 다 옛 글로 닫혔다)
        fresh = [q for q in posts if q["platform"] == "naver" and (q.get("created") or "") >= c["date"]]
        cov = covered_by(c["kw"], fresh)
        c["state"] = (f"다룸({os.path.basename(cov[0])[:-3]})" if cov else f"닫음({c['closed']})" if c["closed"]
                      else "기한 지남" if c["age"] > NEXT_TOPICS_DAYS else "열림")
        out.append(c)
    return out

def next_topics_cmd(rest):
    if "--close" in rest:   # 2026-10-25: 원고 작업 STEP 0이 버린 후보를 닫는다(다음 날 다시 평가하지 않게). 주간 보고가 다시 적으면 열린다
        i = rest.index("--close")
        kw, why = rest[i + 1], (rest[i + 2] if len(rest) > i + 2 else "STEP 0 탈락")
        cur = {norm(c["kw"]): c for c in next_topics()}.get(norm(kw))
        if not cur:
            sys.exit(f"next_topics.tsv에 없는 키워드: {kw}")
        with io.open(os.path.join(KW_DIR, "next_topics.tsv"), "a", encoding="utf-8") as f:
            f.write(f"{cur['date']}\t{cur['kw']}\t{cur['why']}\t{cur['lane'] or ''}\t{now():%m-%d} {why.replace(chr(9), ' ')}\n")
        print(f"닫음: {cur['kw']} — {why}")
        return
    rows = next_topics()
    op = [c for c in rows if c["state"] == "열림"]
    print(f"### 주간 분석 다음 편 후보 — 열림 {len(op)}개 (analytics/keywords/next_topics.tsv)\n")
    for c in rows if "--all" in rest else op:
        print(f"- [{c['state']}] **{c['kw']}** · {c['lane'] or '레인?'} · {c['date']} 주 — {c['why']}")
    if not op:
        print("- 열린 후보 없음 — 큐 순서대로 고른다")

def title_head(t):
    """제목의 머리 구절 — 상위 글 제목은 '키워드, 부제' 꼴이 많아 첫 구분자 앞이 곧 노린 키워드다."""
    t = re.sub(r"^\s*(\[[^\]]*\]|\([^)]*\)|\d{4}년?)\s*", "", html.unescape(t))
    h = re.split(r"[,|:｜?!…(\[—–]| - |·{2,}|\.{2,}", t)[0].strip(" \"'“”‘’")
    return h if 4 <= len(norm(h)) <= 18 and 1 <= len(h.split()) <= 5 else None

def channel_titles(blog):
    v = C_CHAN.get(blog)
    if v is None:
        v = []
        for ep, key in (("popular-post-list", "popularPostList"), ("post-list?categoryNo=0&itemCount=30&page=1", "items")):
            try:
                r = json.loads(http(f"https://m.blog.naver.com/api/blogs/{blog}/{ep}", headers={**UA_MO, "Referer": f"https://m.blog.naver.com/{blog}"}, pause=0.25)).get("result", {})
                v += [x.get("titleWithInspectMessage") or "" for x in (r.get(key) or [])]
            except Exception:
                pass
        C_CHAN.put(blog, v)
    return v

def discover(fast=False, log=print):
    cands = {}   # norm → dict
    def add(kw, lane, src, pos=9, engine="n"):
        kw = re.sub(r"\s+", " ", kw).strip()
        if not 3 <= len(norm(kw)) <= 22:
            return
        c = cands.setdefault(norm(kw), {"kw": kw, "lane": lane, "src": set(), "pos": 9, "nav": False, "goo": False})
        c["src"].add(src)
        c["pos"] = min(c["pos"], pos)
        c["lane"] = c["lane"] or lane
        c["nav" if engine == "n" else "goo"] = True

    seeds = read_seeds()
    log(f"· 씨앗어 {len(seeds)}개 자동완성 확장")
    for s, lane in seeds:
        for i, x in enumerate(ac_naver(s)):
            add(x, lane, "씨앗", i, "n")
        for i, x in enumerate(ac_google(s)):
            add(x, lane, "씨앗", i, "g")
    inflow = read_tsv("inflow.tsv")
    log(f"· 내 유입 검색어 {len({r[2] for r in inflow if len(r) > 2})}개 확장")
    for r in inflow:
        if len(r) < 3:
            continue
        # 2026-09-27: 구글 서치콘솔 검색어(플랫폼 google)는 구글 자동완성으로 넓힌다 — 티스토리 쪽 수요 신호.
        # 전에는 전부 네이버 자동완성으로만 넓혀 구글 수요가 큐에 안 들어왔다
        if r[1] == "google":
            for i, x in enumerate(ac_google(r[2])):
                add(x, lane_of(x), "유입", i, "g")
        else:
            for i, x in enumerate(ac_naver(r[2])):
                add(x, lane_of(x), "유입", i, "n")
    weekly = [c for c in next_topics() if c["state"] == "열림"]
    log(f"· 주간 분석 다음 편 후보 {len(weekly)}개 확장")
    for c in weekly:
        add(c["kw"], c["lane"], "주간", 0, "n")
        for i, x in enumerate(ac_naver(c["kw"])):
            add(x, lane_of(x) or c["lane"], "주간", i, "n")
    trend = read_trend_seeds()
    log(f"· 트렌드 후보 {len(trend)}개 확장")
    for s in trend:
        for i, x in enumerate(ac_naver(s)):
            add(x, lane_of(x), "트렌드", i, "n")
    if not fast:
        chans = [r[0] for r in read_tsv("channels.txt")]
        log(f"· 경쟁 채널 {len(chans)}곳 제목 수집")
        heads = {}
        for b in chans:
            for t in channel_titles(b):
                h = title_head(t)
                if h and lane_of(h):
                    heads.setdefault(norm(h), h)
                elif h:
                    note_unknown(h, "채널머리")   # F1
        log(f"  머리 구절 {len(heads)}개 → 자동완성 정확 일치만 통과")
        for h in heads.values():
            sug = ac_naver(h)
            if verdict(h, sug) == "정확":
                add(h, lane_of(h), "채널", 5, "n")
                for i, x in enumerate(sug[:5]):
                    add(x, lane_of(x), "채널", 5 + i, "n")
    save_caches()
    return list(cands.values())


# ───────────────────────── 시즌 ─────────────────────────
def publish_ref(posts):
    """새 원고가 네이버에 나가는 예상일과 대기 편수 — 오늘 + 대기 원고 ÷ 하루 발행 수.
    계획 슬롯(scheduled:)은 순서용이라 날짜로 쓰지 않는다(2026-09-23: 슬롯은 하루 1편 기준인데 실제는 하루 2편,
    36·37편 사이 비교12는 건너뛰었다). 대기 = 발행 안 됐고 계획 슬롯이 날짜로 적힌 네이버 원고."""
    wait = [p for p in posts if p["platform"] == "naver" and not is_published(p)
            and re.match(r"\d{4}-\d{2}-\d{2}", p["scheduled"])]
    return now().date() + datetime.timedelta(days=math.ceil(len(wait) / POSTS_PER_DAY)), len(wait)

def season_hits(kw, today=None):
    today = today or now().date()
    hits = []
    for r in read_tsv("calendar.tsv"):
        if len(r) < 3:
            continue
        mm, dd = map(int, r[0].split("-"))
        for y in (today.year, today.year + 1):
            d = datetime.date(y, mm, dd)
            left = (d - today).days
            if 5 <= left <= int(r[1]) * 7 and any(norm(k) in norm(kw) for k in r[2].split(",")):
                hits.append((left, r[3] if len(r) > 3 else ""))
    return min(hits) if hits else None


# ───────────────────────── 채점 ─────────────────────────
def clamp(x, lo=0.0, hi=1.0):
    return max(lo, min(hi, x))

def attain(m):
    """1~5위 도달 가능성 0~1. 2026-09-18 실측: 내 글이 3위 안에 든 키워드는 상위 10 일방문 중앙값이 대체로 100 이하,
    제목 정확 일치가 8개 이상인 키워드(식품위생교육·원산지 표시)에서는 13~16위에 그쳤다."""
    if not m or m.get("auth_med") is None:
        return 0.6
    a_auth = clamp(1 - math.log10(max(m["auth_med"], 30) / 30) / 2)      # 30→1.0 · 300→0.5 · 3000→0
    return round(a_auth * (1 - 0.5 * m["exact10"] / 10), 2)

def score(c, has_vol):
    w = {"사장님": 1.0, "양쪽": 0.75}.get(c["intent"], 0)
    at = attain(c.get("serp"))
    if has_vol:
        base = c.get("vol", {}).get("total", 0) * CLICK_SHARE * at
    else:
        d = 0.45 * min(c.get("children", 0), 9) / 9 + 0.35 * (1 - min(c["pos"], 9) / 9) + 0.20 * (1 if c.get("goo_v") in ("정확", "근접") else 0)
        base = 100 * d * at
    if c.get("season"):
        base *= 1.3
    return round(base * w, 1)


# ───────────────────────── 실행: run ─────────────────────────
def _weekly_tools(args):
    """F2: 월요일(KST) 아침 run이 주간 보고(월 10:30) 전에 새 도구 후보 표를 새로 만든다. 실패해도 run은 계속한다."""
    if now().weekday() == 0 or "--tools" in args:
        try:
            tool_candidates()
        except Exception as e:
            print(f"· 새 도구 후보 표 실패(실행은 계속): {type(e).__name__}: {e}")

def run(args):
    fast = "--fast" in args
    qpath = os.path.join(KW_DIR, "queue.md")
    if "--max-age" in args:
        days = float(args[args.index("--max-age") + 1])
        if os.path.exists(qpath) and _epoch() - os.path.getmtime(qpath) < days * 86400:
            gone = stale_candidates(own_posts())
            if not gone:
                print(f"queue.md가 {days:g}일 이내 생성본이고 그 뒤 원고가 후보를 덮지 않아 재사용한다: {qpath}")
                _weekly_tools(args)   # F2는 큐를 다시 쓰는 날에도 월요일이면 만든다(입력은 unknown_terms.tsv뿐)
                return
            print(f"queue.md 뒤에 쓴 원고가 후보 {len(gone)}개를 이미 다뤘다({', '.join(gone[:4])}{' …' if len(gone) > 4 else ''}) — 새로 만든다")
    keys = load_keys()
    replay_start(args, keys)
    print(f"· CLICK_SHARE {CLICK_SHARE_WHY}")
    posts = own_posts()
    ref, waiting = publish_ref(posts)
    print(f"[kw_pipeline] {now():%Y-%m-%d %H:%M} · 검색량 {'검색광고 API (' + os.path.basename(keys['_src']) + ')' if keys else '미연동(대리 신호)'} · 내 글 {len(posts)}편")
    cands = discover(fast)
    print(f"· 후보 {len(cands)}개 발굴")

    kept, dropped, variants = [], {}, []
    nrej = naver_rejects()
    if nrej:
        print(f"· 네이버 거절 기록 {len(nrej)}개(기한 안) — 큐에서 뺀다")
    for c in cands:
        if norm(c["kw"]) in nrej:
            dropped["네이버 거절"] = dropped.get("네이버 거절", 0) + 1
            continue
        c["lane"] = c["lane"] or lane_of(c["kw"])
        c["intent"] = intent_of(c["kw"])
        if not c["lane"] or (c["lane"] and not lane_of(c["kw"]) and not ({"씨앗", "주간"} & c["src"])):
            dropped["레인 밖"] = dropped.get("레인 밖", 0) + 1
            note_unknown(c["kw"], "+".join(sorted(c["src"])))   # F1
            continue
        if c["intent"] not in ("사장님", "양쪽"):
            dropped[c["intent"]] = dropped.get(c["intent"], 0) + 1
            continue
        # 2026-10-05: 장비 레인은 제휴 후보 칸이다. AI 이야기 없는 장비(주방기기)가 레인 상위 칸을 차지해 새 씨앗이 밀려났다
        if c["lane"] == "장비" and (not story_of(c["kw"]) or AFF_EXCLUDE_RE.search(c["kw"])):
            dropped["장비-주제밖"] = dropped.get("장비-주제밖", 0) + 1
            continue
        cov = covered_by(c["kw"], posts)
        if cov:
            c["covered"] = cov
            variants.append(c)
            continue
        kept.append(c)
    # 2026-10-20 후보 풀(Thomas '기본값대로' — 볼트 analytics/키워드후보-로직점검-2026-10-20.md §6): 큐는 매일 처음부터 만들어져
    # 레인 상한·그날 자동완성에서 밀린 후보가 사라졌다(10-05~19 288개 중 90개). 최근 POOL_DAYS일 history 후보를 다시 넣되 저장된 검색량·경쟁도는
    # 쓰지 않는다 — 아래 검색량·2차 자동완성·SERP·도달·판정을 오늘 값으로 다시 거친다(백테스트: 저장값 그대로면 상위 13개 중 7개가 이미 체급 밖)
    pooled = pool_candidates({norm(c["kw"]) for c in cands}, posts)
    kept += pooled
    print(f"· 통과 {len(kept)}개(후보 풀 {len(pooled)}개 포함) / 보유 변형 {len(variants)}개 / 제외 {dropped}")

    related = {}
    if keys:
        vol = volumes([c["kw"] for c in kept + variants], keys, related)
        related.update(known_volumes())        # 이전 실행에서 받아 둔 연관어까지 후보 풀에 넣는다
        for c in kept + variants:
            c["vol"] = vol.get(norm(c["kw"]))
        # API가 돌려준 연관 키워드 중 검색량 300 이상·레인 안·사장님 의도·미보유만 후보로 승격
        have = {norm(c["kw"]) for c in kept + variants}
        for n, v in related.items():
            if n not in have and v["total"] >= 300 and not lane_of(v["kw"]) and 3 <= len(n) <= 22:
                note_unknown(v["kw"], "연관", v["total"])   # F1
            if n in have or v["total"] < 300 or not lane_of(v["kw"]) or not 3 <= len(n) <= 22:
                continue
            it = intent_of(v["kw"])
            if it not in ("사장님", "양쪽"):
                dropped[it] = dropped.get(it, 0) + 1
                continue
            if lane_of(v["kw"]) == "장비" and (not story_of(v["kw"]) or AFF_EXCLUDE_RE.search(v["kw"])):
                dropped["장비-주제밖"] = dropped.get("장비-주제밖", 0) + 1
                continue
            # 연관 키워드는 Thomas가 고른 말이 아니라 네이버가 붙여 준 말이다. 레인 단어 하나만 겹쳐도 딸려 오므로
            # (노트북lm→'노트북', 네이버 예약→'에어팟5 사전예약', 뤼튼→'뤼튼 여성향') 과업 표지를 요구한다.
            if not OWNER.search(v["kw"]) and lane_of(v["kw"]) != "장비":   # 장비 레인은 EQUIP_RE가 사업 맥락을 이미 요구한다
                dropped["연관-과업없음"] = dropped.get("연관-과업없음", 0) + 1
                continue
            if not covered_by(v["kw"], posts):
                kept.append({"kw": v["kw"], "lane": lane_of(v["kw"]), "src": {"연관"}, "pos": 9, "nav": False, "goo": False, "intent": it, "vol": v})
        kept.sort(key=lambda c: -(c.get("vol") or {}).get("total", 0))
    else:
        kept.sort(key=lambda c: (-len(c["src"]), -(c["nav"] and c["goo"]), c["pos"]))

    # 2차 자동완성: 하위 제안 수(수요 폭)와 틈새 후보, 구글 열
    lanes = LANES
    hand_seeds = {norm(k) for k, _ in read_seeds(auto=False)}
    per = 14 if fast else 30                     # 레인별 SERP 조사 수
    def per_lane(items, n):
        out = []
        for ln in lanes:
            xs, per_story = [x for x in items if x["lane"] == ln], {}
            if ln == "장비":   # 2026-10-05: 라벨 변형 10여 개가 장비 칸을 독차지했다 — 같은 AI 이야기(묶음)는 EQUIP_GROUP_CAP개까지,
                # Thomas가 seeds.txt에 직접 넣은 씨앗이 먼저(초소형·볼펜 녹음기 같은 큰 변형이 'AI녹음기'를 밀어냈다)
                xs.sort(key=lambda x: norm(x["kw"]) not in hand_seeds)
                xs = [x for x in xs if per_story.setdefault(story_of(x["kw"]), []).append(x) or len(per_story[story_of(x["kw"])]) <= EQUIP_GROUP_CAP]
            out += xs[:n]
        return out
    # 2026-10-25: 거절 기록은 연관어·후보 풀처럼 위 거르기 뒤에 붙는 출처에도 건다(첫 재생성에서 4개가 연관·풀로 되돌아왔다)
    late = [c for c in kept if norm(c["kw"]) in nrej]
    if late:
        dropped["네이버 거절"] = dropped.get("네이버 거절", 0) + len(late)
        kept = [c for c in kept if norm(c["kw"]) not in nrej]
    short = per_lane(kept, per * 2)
    # 2026-09-27: 검색량 순 상위만 SERP를 보면 경쟁 센 큰 키워드만 조사된다(09-27 큐: 새 후보 37개 중 3위 안 88% 구간 2개).
    # 씨앗 탐색에서 중간 검색량(300~8,000) 160개를 따로 재 보니 34개가 그 구간이었다 → 레인별 중간 검색량 20개를 더 본다
    MID = 15 if fast else 20
    seen = {norm(c["kw"]) for c in short}
    mid = [c for c in kept if norm(c["kw"]) not in seen and 300 <= (c.get("vol") or {}).get("total", 0) <= 8000] if keys else []
    for c in mid:
        c["mid"] = True
    short += per_lane(mid, MID)
    print(f"· 레인별 상위 {per * 2}개 + 중간 검색량 {MID}개씩 {len(short)}개 2차 자동완성")
    for c in short:
        sn = ac_naver(c["kw"])
        c["nav_v"] = verdict(c["kw"], sn)
        by_kids = intent_by_children([x for x in sn if norm(x) != norm(c["kw"])])
        if by_kids:
            c["intent"] = by_kids
        kids = [x for x in sn if norm(x) != norm(c["kw"]) and intent_of(x) in ("사장님", "양쪽")]
        c["children"], c["niche"] = len(kids), kids[:2]
        c["goo_v"] = verdict(c["kw"], ac_google(c["kw"]))
        hit = season_hits(c["kw"], ref)
        if hit:
            c["season"] = hit
    save_caches()
    for c in short:
        if c["intent"] not in ("사장님", "양쪽"):
            dropped[c["intent"]] = dropped.get(c["intent"], 0) + 1
    short = [c for c in short if c["intent"] in ("사장님", "양쪽")
             and (c.get("nav_v") == "정확" or c.get("goo_v") == "정확")]   # 어느 검색창에도 없는 말은 제목 키워드로 못 건다
    short.sort(key=lambda c: -score(c, bool(keys)))
    # 2026-10-21 (나)+(가′) Thomas(키워드후보-로직점검-2026-10-20.md §8-4·§8-5): 최근 OOL_DAYS일 안에 체급 밖으로 잰 말은 SERP를 건너뛰고
    # 저장된 측정으로 체급 밖 목록에 둔다. 그 칸은 같은 레인의 다음 순위(31위 이하 — 전에는 어디로도 못 가던 빈 구간)가 쓴다.
    # 중간 구간 20칸에 31~60위를 섞지 않는다 — 표본 실측에서 31~60위는 중간 구간보다 도달하기 어려웠다(마케팅 3위 안 88% 구간 18% 대 67%)
    known_ool = known_out_of_league()
    skipped = [c for c in short if norm(c["kw"]) in known_ool]
    for c in skipped:
        c["serp"], c["serp_date"] = known_ool[norm(c["kw"])]["serp"], known_ool[norm(c["kw"])]["date"]
    rest = [c for c in short if norm(c["kw"]) not in known_ool]
    short = per_lane([c for c in rest if not c.get("mid")], per) + per_lane([c for c in rest if c.get("mid")], MID)
    print(f"· 레인별 상위 {per}개 + 중간 {MID}개씩 {len(short)}개 SERP 경쟁 조사"
          + (f" — 최근 {OOL_DAYS}일 체급 밖 {len(skipped)}개는 저장된 측정으로 건너뛰고 그 칸을 다음 순위에 줬다" if skipped else ""))
    empty = 0
    for i, c in enumerate(short, 1):
        c["serp"] = serp_metrics(c["kw"])
        c["serp_date"] = f"{now():%Y-%m-%d}"
        empty += c["serp"] is None
        if i % 20 == 0:
            print(f"  {i}/{len(short)}")
            save_caches()
    for c in short + skipped:
        c["score"] = score(c, bool(keys))
    # 도달 게이트 — 2026-09-18 내 글 31개 실측.
    #   일방문 중앙값: ~120이면 3위 안 56%, 120~250은 20%, 250 초과는 0/1 → AUTH_CAP=250
    #   제목 일치(어절 전부, 어순 무시): 0~4개면 3위 안 88%, 5~7개 33%, 8~9개 50%, **10/10은 0/2**
    #     → EXACT_CAP=9. 10/10은 상위 열 칸이 전부 같은 검색어를 노린 제목이라 비집고 들어갈 자리가 없다.
    #     (7로 잡았다가 후보가 절반으로 줄었다 — 그 숫자는 어순을 못 보던 옛 지표로 잰 값이었다)
    # 검색량만으로 줄을 세우면 큰 키워드가 큐를 덮으므로, 못 오르는 칸은 본 목록에서 내린다.
    def reachable(c):
        m = c.get("serp")
        if not m or m.get("auth_med") is None:
            return True                      # 못 읽었으면 사람이 판단한다
        return m["auth_med"] <= AUTH_CAP and m["exact10"] <= EXACT_CAP
    out_of_league = [c for c in short if not reachable(c)] + skipped
    short = [c for c in short if reachable(c)]
    short.sort(key=lambda c: -c["score"])
    out_of_league.sort(key=lambda c: -(c.get("vol") or {}).get("total", 0))
    variants = [c for c in variants if norm(c["kw"]) != norm(c["covered"][1])]   # 내 키워드와 똑같은 말은 정보가 없다
    for c in variants:
        hit = season_hits(c["kw"], ref)
        if hit:
            c["season"] = hit
    short, _ = decision_pass(short, variants)       # 2026-10-08 Phase 4: 기존 글 판정(빼기만 한다, 실패하면 그대로)
    tcands = tistory_candidates(cands, posts, keys)
    save_unknown_terms()   # F1
    _weekly_tools(args)
    ranks = rank_track(posts)
    save_caches()
    write_queue(short, variants, ranks, dropped, bool(keys), parser_broken=(empty > (len(short) + len(out_of_league)) / 2), out_of_league=out_of_league,
                ref=(ref, waiting), posts=posts, tistory=tcands)
    print(f"→ {qpath}")
    replay_finish()


# ───────────────────────── 판정 단계 (Phase 4, 2026-10-08) ─────────────────────────
# 큐 후보마다 blog_taxonomy로 분류(클러스터 → 레인)·수요 3상태·기존 글 판정(CREATE_NEW / UPDATE_EXISTING / REJECT)을 붙인다.
# 레지스트리(clusters.tsv·entities.tsv)와 원고 프론트매터가 정본이고, 여기서 클러스터·레인을 다시 정하지 않는다.
# 이번 단계는 '덧붙이는' 판정이다: covered_by(레거시)가 이미 뺀 후보를 되살리지 않고, 새 판정은 후보를 빼기만 한다(큐는 줄기만 한다).
#   CREATE_NEW → 그대로 둔다(점수 공식은 바꾸지 않는다) · UPDATE_EXISTING → 큐에서 빼고 update_candidates.tsv(보강 인계)
#   REJECT → 큐에서 빼고 rejected.tsv(같은 말이 다시 발굴돼도 이유가 남게)
# 장비 레인은 제휴 재고(update_stock)가 큐 스냅샷을 모으는 흐름이라 이번엔 판정만 기록하고 빼지 않는다.
# 섹션(레인 절)은 아직 레거시 lane_of로 둔다 — per_lane 칸 나눔이 판정 전에 레거시 레인으로 끝나서, 여기서 옮기면 칸 수가 어긋난다.
# 실패하면 기록만 남기고 원래 큐를 그대로 쓴다 — 아침 원고 작업의 사전 단계라 여기서 멈추면 그날 원고가 없다.
REJECTED_F = os.path.join(KW_DIR, "rejected.tsv")
# 적용 범위(Phase 4.5, Thomas 2026-10-08 — 보정이 끝날 때까지 보수적으로). 이 줄 하나로 바꾼다. 점검용으로 환경변수 KW_DECISION_MODE가 덮어쓴다
#   shadow  판정·보고만, 큐는 그대로
#   canary  발행·예약 글과 같은 검색어(REJECT, 규칙 R1)만 큐에서 뺀다. 나머지 UPDATE·REJECT는 보고만
#   enforce UPDATE_EXISTING·REJECT를 모두 큐에서 뺀다(Phase 4 동작)
DECISION_MODE = "enforce"   # 2026-10-25 Thomas('겹친 후보가 큐에 남지 않게'): canary → enforce. 발행 글은 고치지 않으므로(Publish Once 10-10)
                            # UPDATE_EXISTING 후보는 새 글도 보강도 못 된다 — 10-25 큐 150개 중 39개가 이것이었고, 수동 실행 두 번이 3편째를 못 채운 원인이었다
DECISION_MODES = ("shadow", "canary", "enforce")

def decision_mode():
    """Generated: the recorded run's mode."""
    return _DECISION_MODE

def enforced(d, mode):
    """이 판정이 지금 모드에서 큐에서 빠지는가."""
    if mode == "enforce":     # 확신 LOW(모르는 수식어·회사·도구 엇갈림·수요 모르는 도구 변형)는 enforce에서도 빼지 않는다
        return d["decision"] != "CREATE_NEW" and d.get("confidence") != "LOW"
    if mode == "canary":      # 발행·예약 글과 표현만 다른 같은 검색어(EQUIVALENT, 확신 HIGH)만
        return (d["decision"] == "REJECT" and d["matched_status"] in ("published", "scheduled") and d["rule"].startswith("R1")
                and d.get("confidence") == "HIGH")
    return False
REPORT_F = os.path.join(KW_DIR, "decision_report.md")

def demand_evidence(c, inflow):
    """후보의 필드 → 수요 근거 태그(규칙은 blog_taxonomy.demand_from_evidence). 검색량 0·빈 값은 근거가 아니다(API가 안 준 말일 수 있다).
    _cnt가 '< 10'을 5로 바꾸므로 합계 20 미만은 하한값일 수 있어 약한 근거(volume_floor)로만 본다."""
    ev = []
    if c.get("nav_v") == "정확":
        ev.append("autocomplete_exact")
    elif c.get("nav_v") == "근접":
        ev.append("autocomplete_near")
    if c.get("goo_v") in ("정확", "근접"):
        ev.append("google_autocomplete")
    total = (c.get("vol") or {}).get("total") or 0
    if total >= 20:
        ev.append("monthly_volume")
    elif total > 0:
        ev.append("volume_floor")
    if "유입" in (c.get("src") or ()) or norm(c["kw"]) in inflow:
        ev.append("search_inflow")
    if "연관" in (c.get("src") or ()):
        ev.append("related_keyword")
    return ev

def taxonomy_corpus(live=None):
    """판정용 말뭉치를 한 번 만든다 — 실효 상태(라이브 발행 확인으로만 올림)를 먼저 적용한다."""
    pass
    from . import kw_taxonomy as bt
    cs, es = bt.load_clusters(), bt.load_entities()
    arts = bt.apply_live_status(bt.load_articles(), naver_live() if live is None else live)
    return bt, cs, es, bt.Corpus(arts, cs, es)

def judge(c, bt, cs, es, corpus, inflow):
    """후보 하나 → 판정 기록(후보 dict의 'decision'). 분류는 레지스트리, 레거시 레인과 다르면 둘 다 남긴다."""
    tax = bt.classify(c["kw"], cs, es)
    cl = next((x for x in cs if x["id"] == tax["cluster"]), None)
    ev = demand_evidence(c, inflow)
    dm = bt.demand_from_evidence(ev)
    rec = bt.decide(bt.candidate(c["kw"], cs, es), corpus, demand=dm)
    m = rec["matched_article"] or {}
    d = dict(decision=rec["decision"], action=rec["action"], rule=rec["rule"], reason=rec["reason"],
             matched=m.get("id", ""), matched_status=rec["matched_status"] or "", status_source=m.get("status_source", ""),
             cluster=tax["cluster"] or "unresolved", lane=tax["lane"] or "unresolved", cluster_status=cl["status"] if cl else "",
             intent=rec["candidate"]["intent"], entity=tax["entity"], demand=dm, evidence=ev,
             lane_legacy=c.get("lane") or "", drafts=[x["id"] for x in rec["drafts"]],
             facet=rec["candidate"]["facet"], variant_relation=rec["variant_relation"], confidence=rec["confidence"],
             modifiers=(rec["signals"] or {}).get("modifiers", []), entity_conflict=(rec["signals"] or {}).get("entity_conflict", []))
    c["decision"] = d
    return d, rec

def decision_pass(short, variants, live=None, log=print, record=True, mode=None):
    """short(레거시가 남긴 새 글 후보)에 판정을 붙이고 UPDATE·REJECT를 뺀다. variants(레거시가 뺀 보유 변형)는 비교만 한다.
    → (남은 short, 보고용 dict). 어떤 오류든 원래 short를 돌려준다."""
    try:
        mode = mode or decision_mode()
        bt, cs, es, corpus = taxonomy_corpus(live)
        inflow = {norm(r[2]) for r in read_tsv("inflow.tsv") if len(r) > 2}
        kept, moved, recs = [], [], []
        for c in short:
            d, rec = judge(c, bt, cs, es, corpus, inflow)
            d["enforced"] = enforced(d, mode) and c.get("lane") != "장비"
            if not d["enforced"]:
                kept.append(c)
            else:
                moved.append(c)
                recs.append(rec)
        for c in variants:
            judge(c, bt, cs, es, corpus, inflow)
        if record:
            n_up = bt.append_updates([r for r in recs if r["decision"] == "UPDATE_EXISTING"])
            n_rej = append_rejected([c for c in moved if c["decision"]["decision"] == "REJECT"])
        else:
            n_up = n_rej = 0
        info = dict(short=short, kept=kept, moved=moved, variants=variants, corpus=corpus, n_up=n_up, n_rej=n_rej, mode=mode)
        if record:
            write_decision_report(info)
        log(f"· 판정({mode}): 큐 유지 {len(kept)} · 보강으로 뺌 {sum(c['decision']['decision'] == 'UPDATE_EXISTING' for c in moved)} · 중복으로 뺌 "
            f"{sum(c['decision']['decision'] == 'REJECT' for c in moved)} (인계 +{n_up}, 기각 기록 +{n_rej}) → {os.path.basename(REPORT_F)}")
        return kept, info
    except Exception as e:
        import traceback
        log(f"  ! 판정 단계 실패 — 원래 큐를 그대로 쓴다: {type(e).__name__}: {e}")
        traceback.print_exc()
        return short, None

def append_rejected(cands, path=None):
    """REJECT 후보를 남긴다(키워드당 한 줄 — 다시 발굴되면 날짜만 남은 첫 줄이 이유를 말한다)."""
    path = path or REJECTED_F
    have = {l.split("\t")[0] for l in io.open(path, encoding="utf-8") if l.strip() and not l.startswith("#")} if os.path.exists(path) else set()
    new = [c for c in cands if c["kw"] not in have]
    if not new:
        return 0
    first = not os.path.exists(path)
    with io.open(path, "a", encoding="utf-8") as f:
        if first:
            f.write("# 판정 기각(REJECT) — kw_pipeline 판정 단계가 큐에서 뺀 키워드. 같은 검색어·같은 답을 가진 기존 글이 있다(blog_taxonomy decide)\n")
            f.write("# 형식: 키워드<TAB>날짜<TAB>맞선 글<TAB>규칙<TAB>이유. 키워드당 한 줄(처음 기각된 날)\n")
        for c in new:
            d = c["decision"]
            f.write("\t".join((c["kw"], f"{now():%Y-%m-%d}", d["matched"], d["rule"], d["reason"])) + "\n")
    return len(new)

def shadow_stats(short, variants):
    """레거시 covered_by와 새 판정 비교. 일치 = (레거시 덮음 ⇔ 새 판정 UPDATE·REJECT)."""
    rows = [(c, False) for c in short if c.get("decision")] + [(c, True) for c in variants if c.get("decision")]
    st = dict(total=len(rows), agree=0, disagree=0, covered_new=0, uncovered_update=0, uncovered_update_draft=0, uncovered_reject=0, covered_update=0, covered_reject=0)
    dis = []
    for c, covered in rows:
        d = c["decision"]
        new_cov = d["decision"] != "CREATE_NEW"
        if covered == new_cov:
            st["agree"] += 1
            st["covered_update" if d["decision"] == "UPDATE_EXISTING" else "covered_reject"] += covered and 1
        else:
            st["disagree"] += 1
            dis.append((c, covered))
            if covered:
                st["covered_new"] += 1
            elif d["decision"] == "REJECT":
                st["uncovered_reject"] += 1
            elif d["matched_status"] == "draft":
                st["uncovered_update_draft"] += 1
            else:
                st["uncovered_update"] += 1
    return st, dis

def write_decision_report(info, path=None):
    """판정 결과 보기(실행마다 덮어쓴다): 분포·레거시 비교·원고 검토·발행 글 보강·미분류 클러스터 근거."""
    import collections
    short, kept, moved, variants = info["short"], info["kept"], info["moved"], info["variants"]
    D = lambda c: c["decision"]
    st, dis = shadow_stats(short, variants)
    L = [f"# 판정 보고 — {now():%Y-%m-%d %H:%M}", "",
         "> `tools/kw_pipeline.py run` 의 판정 단계(blog_taxonomy decide)가 만든 파일이다. 실행마다 덮어쓴다. 원고·발행 글은 고치지 않는다.", "",
         "## 분포 (새 글 후보 = 레거시가 남긴 큐 후보)", "",
         f"- 판정: " + " · ".join(f"{k} {v}" for k, v in collections.Counter(D(c)["decision"] for c in short).most_common()),
         f"- 행동: " + " · ".join(f"{k} {v}" for k, v in collections.Counter(D(c)["action"] for c in short).most_common()),
         f"- 수요: " + " · ".join(f"{k} {v}" for k, v in collections.Counter(D(c)["demand"] for c in short).most_common()),
         f"- 새 글(CREATE_NEW)의 클러스터 상태: " + " · ".join(f"{k or 'unresolved'} {v}" for k, v in collections.Counter(D(c)["cluster_status"] for c in kept if D(c)["decision"] == "CREATE_NEW").most_common()),
         f"- 적용 모드 **{info['mode']}** — 큐에서 뺀 후보 {len(moved)}개(보강 인계 +{info['n_up']}, 기각 기록 +{info['n_rej']}). enforce였다면 뺐을 후보 "
         f"{sum(1 for c in short if D(c)['decision'] != 'CREATE_NEW' and c.get('lane') != '장비')}개. 장비 레인은 판정만 기록하고 빼지 않는다", ""]
    L += ["## 레거시 covered_by 비교 (그림자)", "",
          f"- 전체 {st['total']} (레거시가 남긴 후보 {len([c for c in short if c.get('decision')])} + 레거시가 뺀 보유 변형 {len([c for c in variants if c.get('decision')])}) · 일치 {st['agree']} · 불일치 {st['disagree']}",
          f"- 레거시 덮음 → 새 CREATE_NEW {st['covered_new']} · 레거시 안 덮음 → 새 UPDATE_EXISTING(발행 글) {st['uncovered_update']} · (원고) {st['uncovered_update_draft']} · → 새 REJECT {st['uncovered_reject']}",
          "- 보유 변형은 레거시 흐름에서 자동완성을 재지 않아 수요가 대부분 UNKNOWN이다(비교의 비대칭)", ""]
    for c, covered in dis:
        d = D(c)
        leg = f"덮음 — {os.path.basename(c['covered'][0])[:26]} ('{c['covered'][1]}')" if covered else "안 덮음"
        L.append(f"- **{c['kw']}** · 레거시 {leg} · 새 {d['decision']}({d['action']}) → {d['matched'] or '—'}[{d['matched_status'] or '—'}] · {d['reason'][:140]}")
    L += ["", "## 원고 검토 (review_draft · consolidate_drafts — 발행 글 보강 주 3건 상한과 별개)", ""]
    rv = [c for c in short + variants if D(c)["action"] in ("review_draft", "consolidate_drafts")]
    L += [f"- {D(c)['action']} · **{c['kw']}** → {D(c)['matched']} · {D(c)['reason'][:140]}" for c in rv] or ["- 없음"]
    L += ["", "## 발행 글 보강 후보 (update_published — 주 3건 상한 대상)", ""]
    up = [c for c in short + variants if D(c)["action"] == "update_published"]
    L += [f"- **{c['kw']}** → {D(c)['matched']}[{D(c)['status_source']}] · 수요 {D(c)['demand']} · {D(c)['reason'][:140]}" for c in up] or ["- 없음"]
    L += ["", "## 중복 기각 (REJECT)", ""]
    L += [f"- **{c['kw']}** → {D(c)['matched']} · {D(c)['rule']}" for c in short + variants if D(c)["decision"] == "REJECT"] or ["- 없음"]
    L += ["", "## 미분류 — 기존 클러스터가 받지 못한 후보 (새 클러스터는 큐 키워드 2개 이상일 때 CANDIDATE 검토, 자동 생성 안 함)", ""]
    un = [c for c in short if D(c)["cluster"] == "unresolved"]
    L += [f"- {c['kw']} (레거시 레인 {D(c)['lane_legacy']}, 수요 {D(c)['demand']})" for c in un] or ["- 없음"]
    L += ["", "## 레인 차이 — 레지스트리(클러스터) ↔ 레거시 lane_of", ""]
    diff = [c for c in short + variants if D(c)["lane"] not in ("unresolved", D(c)["lane_legacy"])]
    L += [f"- {c['kw']}: 레지스트리 {D(c)['lane']}({D(c)['cluster']}) ↔ 레거시 {D(c)['lane_legacy']}" for c in diff] or ["- 없음"]
    st_src = collections.Counter(a.get("status_source", "frontmatter") for a in info["corpus"].arts)
    L += ["", "## 말뭉치 실효 상태", "", "- " + " · ".join(f"{k} {v}" for k, v in st_src.most_common())]
    L += [f"- 라이브로 올린 글: {a['id']} ({a['frontmatter_status']} → published, {a['status_source']})" for a in info["corpus"].arts if a.get("status_source", "frontmatter") != "frontmatter"]
    io.open(path or REPORT_F, "w", encoding="utf-8").write("\n".join(L) + "\n")

def decision_tag(c):
    """큐 한 줄에 붙일 짧은 판정 꼬리."""
    d = c.get("decision")
    if not d:
        return ""
    cl = "미분류" if d["cluster"] == "unresolved" else f"{d['cluster']}({d['cluster_status']})"
    hold = f"({d['action']} → {d['matched']} · 큐 유지, decision_report.md)" if d["decision"] != "CREATE_NEW" and not d.get("enforced") else ""
    return f"판정 {d['decision']}{hold} · {cl} · 수요 {d['demand']}" + (f"({'·'.join(d['evidence'])})" if d["evidence"] else "")


# ───────────────────────── Slot C 그림자 (Phase 6, 2026-10-08) ─────────────────────────
# '오늘 세 번째 글을 쓴다면 무엇이 가장 가치 있나'를 매일 하나 골라 기록만 한다. 실제 발행은 하루 2편 그대로.
# A/B는 코드가 아니라 아침 원고 작업(Claude)이 큐에서 고른다 — 그래서 원고 작업이 끝난 뒤 '오늘 만든 일반 원고'를 A/B로 읽고, 남은 큐 후보에서 고른다.
# 읽고 기록만 한다: 큐(queue.md·history)·원고·발행·점수 공식은 바꾸지 않는다. 오류가 나면 C 기록만 빠진다(A/B와 무관).
# 순위는 이 단계 전용 층이다 — 기존 점수(score)를 바꾸지 않고, 아래 가중치는 그림자 평가용이다(사람이 14회 이상 보고 정한다).
SLOTC_F = os.path.join(KW_DIR, "slot_c_shadow.tsv")
SLOTC_REPORT_F = os.path.join(KW_DIR, "slot_c_report.md")
# 2026-10-09 Thomas: 표본 자격은 실행 출처(cron/manual)가 아니라 생산 동등성으로 정한다. 공식 TSV(cron 기록, 날짜당 한 줄)는 그대로 두고,
# 승인 수동 실행은 이 파일에 실제 실행 시각 단위로 따로 남긴다. 집계(slot_c_eval)가 두 파일을 합치고 같은 생산 슬롯은 하나만 센다.
SLOTC_MANUAL_F = os.path.join(KW_DIR, "slot_c_manual_runs.tsv")
SLOTC_MANUAL_EXTRA = ("actual_run_time", "execution_type", "operator_approved", "production_slot", "equivalence", "equivalence_note")
SLOTC_APPROVED_TYPES = ("approved_early_run", "approved_manual_run")
SLOTC_TARGET = 14
# 2026-10-08 Phase 6.1에서 고정(Freeze) — 14회 그림자 평가 동안 명백한 운영 버그가 아니면 가중치·규칙을 바꾸지 않는다(같은 기준으로 비교하려고).
#   같은 클러스터는 질문이 같을 때만 강하게(−0.5), 다른 질문이면 약하게(−0.2). 시간: 지난 기간 −0.2(수요 CONFIRMED·지난 기준을 찾는 말이면 0),
#   다가올 기간 +0.1(수요 CONFIRMED일 때만). 이번·무시간·모호는 0
SLOTC_W = dict(base=1.0, demand={"CONFIRMED": 0.6, "WEAK": 0.2, "UNKNOWN": 0.0}, status={"ACTIVE": 0.4, "CANDIDATE": 0.2},
               gap=0.4, link=0.3, safe=0.2, same_cluster_same_facet=-0.5, same_cluster_distinct_facet=-0.2, same_entity_facet=-0.6,
               recent=-0.1, low_conf=-0.3, expired=-0.2, upcoming_confirmed=0.1)
SLOTC_COLS = ("date", "slot_a", "slot_b", "ab_source", "keyword", "lane", "cluster", "facet", "intent", "entity", "demand", "priority_score",
              "decision", "cluster_status", "internal_link_opportunities", "content_gap", "diversity_reason", "selection_reason",
              "runner_up", "runner_up_reason", "shadow_score", "temporal_status", "target_period", "a_article_id", "b_article_id", "run_source",
              "manual", "manual_note")
# 지난 해 기준을 일부러 찾는 말 — 이런 말이 있으면 지난 기간이어도 감점하지 않는다(소급·정정 신고·지난 급여 계산·연도별 비교)
SLOTC_HISTORICAL = re.compile(r"소급|정정|과거|연도별|년도별|비교|지난")
# 다양성 사유의 표지 — 지표가 이 문자열로 센다(겹치지 않게 둔다)
DIV_SAME_FACET, DIV_DISTINCT_FACET, DIV_TOOL = "같은 클러스터·같은 질문", "같은 클러스터·다른 질문", "같은 질문·다른 도구"
# 이 블로그 범위 밖 — 금융상품·대출(YMYL)·잡음. 슬롯 C로 고르지 않는다
SLOTC_OUT = re.compile(r"대출|카드 ?추천|보험 ?추천|주식|코인|투자")
EXPANSION_GROUPS = (("카카오톡 채널", r"카카오톡|카톡 ?채널|카카오 ?채널"), ("당근 비즈니스", r"당근"), ("쿠폰", r"쿠폰"),
                    ("촬영·음향 장비", r"짐벌|조명|마이크|스피커|사이니지"))

def general_article_files():
    """A/B가 될 수 있는 파일 — 네이버 일반 원고(제휴 재고 제외)의 볼트 상대 경로. 실행 전후 스냅샷의 정의는 여기 하나다."""
    root = os.path.join(VAULT, "content", "naver")
    return sorted(os.path.relpath(p, VAULT) for p in glob.glob(os.path.join(root, "**", "*.md"), recursive=True) if "/제휴/" not in "/" + os.path.relpath(p, root))

def todays_ab(posts, today=None):
    """오늘(KST) 만든 일반 네이버 원고. Phase 6.1부터 Slot C는 이것을 A/B로 쓰지 않는다(수동 원고·재실행을 가리지 못한다) — 실행 전후 스냅샷을 쓴다."""
    day = today or f"{now():%Y-%m-%d}"
    xs = [p for p in posts if p["platform"] == "naver" and "/제휴/" not in "/" + p["file"] and p.get("created") == day and p["keywords"]]
    return sorted(xs, key=lambda p: p["file"])[:2]

def recent_posts(posts, days=7, today=None):
    t = datetime.date.fromisoformat(today or f"{now():%Y-%m-%d}")
    def d(p):
        for k in ("published", "scheduled", "created"):
            try:
                return datetime.date.fromisoformat((p.get(k) or "")[:10])
            except ValueError:
                pass
        return None
    return [p for p in posts if p["platform"] == "naver" and d(p) and 0 <= (t - d(p)).days <= days]

def _facet_of_kw(bt, kw, es, intent):
    a = bt.analyze_kw(kw, es)
    fams = a[1] - {"AI"}
    if fams == {"deadline"} and all(bt.DATE_RX.match(w) or re.fullmatch(r"20\d\d", w) for w in a[3]):
        fams = set()       # '26년'·'2027'은 판(版)이지 '기한' 질문이 아니다
    return sorted(fams, key=lambda f: bt.FACET_STAGE.get(f, 9))[0] if fams else bt.INTENT_FACET.get(intent, "")

def select_slot_c(cands, ab_kws, tx, recent_kws=(), posts=None, today=None):
    """큐 후보 → (선정, 차점, 전체 평가, 확장 후보). 후보 dict는 바꾸지 않는다(복사본에 판정을 붙인다)."""
    bt, cs, es, corpus = tx
    day = today or f"{now():%Y-%m-%d}"
    # 연도가 든 기존 글 키워드(연도 변형을 찾을 때만 본다) — (글 id, 키워드)
    dated = [(a["id"], k) for a in corpus.arts for k in a["keywords"] if bt.temporal_status(k, day)["target_year"]]
    inflow = {norm(r[2]) for r in read_tsv("inflow.tsv") if len(r) > 2}
    ab = []
    for k in ab_kws:
        tax = bt.classify(k, cs, es)
        ab.append(dict(kw=k, cluster=tax["cluster"], entity=set(tax["entity"]), facet=_facet_of_kw(bt, k, es, bt.suggest_intent(k)),
                       core=bt.analyze_kw(k, es)[0]))
    rec_cl = collections.Counter(bt.classify(k, cs, es)["cluster"] for k in recent_kws)
    pub_by_cluster = collections.defaultdict(set)
    for a in corpus.arts:
        if a["status"] == "published":
            pub_by_cluster[a["cluster"]].add(bt._target_facet(corpus.an[a["id"]], a["intent"]))
    rows, expansion = [], []
    scores = sorted((c.get("score") or 0) for c in cands)
    for c0 in cands:
        c = dict(c0)
        d, _ = judge(c, bt, cs, es, corpus, inflow)
        kw = c["kw"]
        why_out = None
        if norm(kw) in {norm(x) for x in ab_kws}:
            why_out = "오늘 A/B"
        elif d["decision"] != "CREATE_NEW":
            why_out = f"{d['decision']}({d['action']})"
        elif c.get("lane") == "장비" or d["lane"] == "장비":
            why_out = "장비 레인 — 제휴 재고 흐름"
        elif SLOTC_OUT.search(kw) or c.get("intent") not in (None, "사장님", "양쪽"):
            why_out = "범위 밖(금융상품·소비자 의도 등)"
        elif posts is not None and covered_by(kw, posts):
            why_out = "레거시 covered_by가 막는다(우회하지 않음)"
        elif d["cluster"] == "unresolved":
            grp = next((g for g, rx in EXPANSION_GROUPS if re.search(rx, kw)), None)
            # 레거시 레인이 있으면(실무·가게 마케팅 …) 기존 클러스터의 match 규칙이 못 받은 말일 가능성 — 사람이 보고 규칙을 넓히거나 버린다
            kind = (("cluster_expansion_candidate: " + grp) if grp else "entity_only" if d["entity"]
                    else f"rule_gap — 기존 클러스터 규칙이 못 받음(레거시 레인 {d['lane_legacy']}, 사람 확인)" if d["lane_legacy"] else "noise_or_scope")
            expansion.append(dict(keyword=kw, kind=kind, demand=d["demand"]))
            why_out = "unresolved — 자동 선정 금지(확장 후보로만)"
        if why_out:
            rows.append(dict(kw=kw, out=why_out, d=d))
            continue
        facet = _facet_of_kw(bt, kw, es, d["intent"])
        core = bt.analyze_kw(kw, es)[0]
        temporal = bt.temporal_status(kw, day)
        # A/B와 겹침 — 같은 클러스터·같은 질문·같은 주제면 뺀다. 같은 클러스터·같은 질문(다른 주제, 또는 연도만 다른 판)은 강한 감점,
        # 같은 클러스터·다른 질문은 약한 감점(서로 독립 검색일 수 있다: 주휴수당 계산 ↔ 주휴수당 지급기준)
        div, pen = [], 0.0
        for x in ab:
            same_cl = x["cluster"] and x["cluster"] == d["cluster"]
            same_core = bool(core) and bt.core_sim_fuzzy(core, x["core"]) >= bt.CORE_NEAR
            same_ent_q = bool(set(d["entity"]) & x["entity"] or (set(d["entity"]) and x["entity"])) and facet == x["facet"] and not same_core
            yv = same_cl and bt.temporal_relation(kw, x["kw"], es, None, day) == "YEAR_VARIANT"
            if same_cl and facet == x["facet"] and (same_core or not core) and not yv:
                div.append(f"A/B '{x['kw']}'와 {DIV_SAME_FACET}·같은 주제")
                pen = None
                break
            if same_ent_q:
                div.append(f"A/B '{x['kw']}'와 {DIV_TOOL}({facet})"); pen += SLOTC_W["same_entity_facet"]
            elif same_cl and (facet == x["facet"] or yv):
                div.append(f"A/B '{x['kw']}'와 {DIV_SAME_FACET}" + ("(연도만 다른 판 YEAR_VARIANT)" if yv else "(다른 주제)")); pen += SLOTC_W["same_cluster_same_facet"]
            elif same_cl:
                div.append(f"A/B '{x['kw']}'와 {DIV_DISTINCT_FACET}"); pen += SLOTC_W["same_cluster_distinct_facet"]
        if pen is None:
            rows.append(dict(kw=kw, out=f"A/B와 {DIV_SAME_FACET}·같은 주제(다양성)", d=d))
            continue
        if rec_cl.get(d["cluster"]):
            div.append(f"최근 7일 같은 클러스터 {rec_cl[d['cluster']]}편"); pen += SLOTC_W["recent"] * rec_cl[d["cluster"]]
        # 시간 — 순위 보조 신호일 뿐 판정은 바꾸지 않는다. 더 새 해의 글이 있다는 이유로 감점하지 않는다
        tst = temporal["status"]
        hist = bool(SLOTC_HISTORICAL.search(kw))
        t_adj = (SLOTC_W["expired"] if tst == "EXPIRED_PERIOD" and d["demand"] != "CONFIRMED" and not hist
                 else SLOTC_W["upcoming_confirmed"] if tst == "UPCOMING_PERIOD" and d["demand"] == "CONFIRMED" else 0.0)
        year_variants = sorted({aid for aid, k in dated if bt.temporal_relation(kw, k, es, cs, day) == "YEAR_VARIANT"}) if temporal["target_year"] else []
        gap = bool(pub_by_cluster.get(d["cluster"])) and facet and facet not in pub_by_cluster[d["cluster"]]
        links = [x for x in bt.link_candidates(bt.candidate(kw, cs, es), corpus)["recommended"] if x["relationship"]["priority"] in (1, 2)]
        safe = d["variant_relation"] in ("DISTINCT_FACET", "NONE")
        base = (scores.index(c.get("score") or 0) + 1) / max(1, len(scores))     # 기존 점수의 순위(점수 자체는 바꾸지 않는다)
        adj = dict(base=round(SLOTC_W["base"] * base, 3), demand=SLOTC_W["demand"].get(d["demand"], 0), status=SLOTC_W["status"].get(d["cluster_status"], 0),
                   gap=SLOTC_W["gap"] if gap else 0, link=SLOTC_W["link"] if links else 0, safe=SLOTC_W["safe"] if safe else 0,
                   low_conf=SLOTC_W["low_conf"] if d["confidence"] == "LOW" else 0, diversity=round(pen, 3), temporal=t_adj)
        s = sum(adj.values())
        rows.append(dict(kw=kw, d=d, facet=facet, gap=gap, links=links, safe=safe, div=div, base=round(base, 3), shadow=round(s, 3),
                         score=c.get("score"), lane=d["lane"], adj=adj, temporal=temporal, historical=hist, year_variants=year_variants))
    ok = sorted([r for r in rows if "shadow" in r], key=lambda r: -r["shadow"])
    return (ok[0] if ok else None), (ok[1] if len(ok) > 1 else None), rows, expansion

def _slotc_reason(r):
    d = r["d"]
    t = r.get("temporal") or {}
    bits = [f"수요 {d['demand']}", f"{d['cluster']}({d['cluster_status']})", "같은 질문의 발행 글 없음(빈 칸)" if r["gap"] else "클러스터에 같은 질문 글 있음",
            f"P1/P2로 이을 발행 글 {len(r['links'])}개" if r["links"] else "이을 발행 글 없음(새 주제일 수 있다)",
            "기존 글과 다른 질문" if r["safe"] else f"관계 {d['variant_relation']}·확신 {d['confidence']}"]
    if t.get("status") and t["status"] != "TIMELESS":
        bits.append(f"시간 {t['status']}({t['target_period'] or '—'})" + (f" · 연도만 다른 기존 글 {','.join(x[:3] for x in r['year_variants'])}(중복 아님)" if r.get("year_variants") else ""))
    return " · ".join(bits + (r["div"] or ["A/B와 겹침 낮음"]))

def _read_slotc(path=None):
    """그림자 기록 → dict 목록. 열은 파일의 '# 형식:' 줄을 따른다 — Phase 6의 23열 기록도 읽는다(그때는 run_source가 없었고, 10-07 한 줄은 사람이 돌린 리허설이다)."""
    path = path or SLOTC_F
    if not os.path.exists(path):
        return []
    cols, rows = None, []
    for l in io.open(path, encoding="utf-8"):
        if l.startswith("# 형식:"):
            cols = l.split(":", 1)[1].strip().split("<TAB>")
        elif l.strip() and not l.startswith("#"):
            v = l.rstrip("\n").split("\t")
            r = dict(zip(cols or SLOTC_COLS, v + [""] * len(cols or SLOTC_COLS)))
            if cols and "run_source" not in cols:
                r["run_source"] = "manual"
            rows.append({k: r.get(k, "") for k in SLOTC_COLS})
    return rows

def _write_slotc(rows, path=None):
    with io.open(path or SLOTC_F, "w", encoding="utf-8") as f:
        f.write("# Slot C 그림자 기록(Phase 6·6.1) — kw_pipeline slotc 가 원고 작업 뒤 하루 한 줄. 실제 글은 만들지 않는다. manual 칸은 사람이 GOOD/BORDERLINE/BAD로 적는다\n")
        f.write("# 형식: " + "<TAB>".join(SLOTC_COLS) + "\n")
        for r in sorted(rows, key=lambda r: r["date"]):
            f.write("\t".join((r.get(k) or "").replace("\t", " ").replace("\n", " ") for k in SLOTC_COLS) + "\n")

def _skipped(r):
    return r["ab_source"].startswith("SKIPPED")

def _read_slotc_manual(path=None):
    """승인 수동 실행 기록 → dict 목록(SLOTC_COLS + SLOTC_MANUAL_EXTRA). 열은 파일의 '# 형식:' 줄을 따른다."""
    path, cols_all = path or SLOTC_MANUAL_F, SLOTC_COLS + SLOTC_MANUAL_EXTRA
    if not os.path.exists(path):
        return []
    cols, rows = None, []
    for l in io.open(path, encoding="utf-8"):
        if l.startswith("# 형식:"):
            cols = l.split(":", 1)[1].strip().split("<TAB>")
        elif l.strip() and not l.startswith("#"):
            r = dict(zip(cols or cols_all, l.rstrip("\n").split("\t")))
            rows.append({k: r.get(k, "") for k in cols_all})
    return rows

def _write_slotc_manual(rows, path=None):
    """실제 실행 시각이 키다 — 같은 날 수동 실행이 둘이어도 서로 덮지 않는다."""
    cols_all = SLOTC_COLS + SLOTC_MANUAL_EXTRA
    with io.open(path or SLOTC_MANUAL_F, "w", encoding="utf-8") as f:
        f.write("# Slot C 승인 수동 실행 기록 — 공식 TSV(cron)와 열이 같고 뒤에 실행 메타 6열. equivalence는 사람이 검증한 판정"
                "(PASS만 공식 집계, PENDING·FAIL은 제외). 집계: slot_c_eval (Thomas 2026-10-09)\n")
        f.write("# 형식: " + "<TAB>".join(cols_all) + "\n")
        for r in sorted(rows, key=lambda r: r["actual_run_time"]):
            f.write("\t".join((r.get(k) or "").replace("\t", " ").replace("\n", " ") for k in cols_all) + "\n")

def _production_slot(r):
    """생산 슬롯 = A 원고의 예약일(날짜). 수동 기록은 저장된 값, cron 기록은 원고 프론트매터에서 읽는다(공식 TSV 형식은 그대로).
    원고를 다시 예약하면 슬롯도 따라 움직인다."""
    if r.get("production_slot"):
        return r["production_slot"]
    aid = r.get("a_article_id")
    for p in ([os.path.join(VAULT, "content", "naver", aid + ".md"), os.path.join(VAULT, "content", "naver", "제휴", aid + ".md")] if aid else []):
        if os.path.exists(p):
            m = re.search(r"^scheduled:[ \t]*(\d{4}-\d{2}-\d{2})", io.open(p, encoding="utf-8").read(), re.M)
            return m.group(1) if m else ""
    return ""

def slot_c_eval(path=None, manual_path=None):
    """공식 평가 표본(Thomas 2026-10-09): 생산 동등 실행 14개. 출처(cron/manual)는 자격 기준이 아니고 보존만 한다.
    - 공식 TSV의 cron 기록: SKIPPED가 아니고 후보가 있으면 VALID. 공식 TSV의 비-cron 줄(10-07 리허설)은 리허설로 뺀다.
    - 수동 기록: 승인 유형(SLOTC_APPROVED_TYPES)·operator_approved=true·equivalence=PASS일 때만 VALID 후보.
    - 같은 생산 슬롯에 VALID가 여럿이면 하나만 센다 — cron 우선, 그다음 이른 실행. 나머지는 DUPLICATE_EXCLUDED."""
    obs = [dict(r, origin="cron" if r["run_source"] == "cron" else "rehearsal", actual_run_time=r["date"]) for r in _read_slotc(path)]
    obs += [dict(r, origin="manual") for r in _read_slotc_manual(manual_path)]
    for o in obs:
        o["slot"] = _production_slot(o)
        if _skipped(o):
            o["status"] = "SKIPPED"
        elif o["origin"] == "rehearsal" or (o["origin"] == "manual" and o["execution_type"] not in SLOTC_APPROVED_TYPES):
            o["status"] = "EXCLUDED_REHEARSAL"
        elif o["origin"] == "manual" and o["operator_approved"] != "true":
            o["status"] = "EXCLUDED_UNAPPROVED"
        elif o["origin"] == "manual" and o["equivalence"] != "PASS":
            o["status"] = "EXCLUDED_NOT_EQUIVALENT"
        elif not o["keyword"]:
            o["status"] = "INVALID"
        else:
            o["status"] = "VALID"
            if not o["slot"] and o["origin"] == "cron":      # 원고를 못 찾아도 기존 cron 표본은 지킨다 — 실행 날짜를 슬롯으로
                o["slot"] = "cron:" + o["date"]
            elif not o["slot"]:
                o["status"] = "INVALID"
    reps = {}
    for o in sorted((o for o in obs if o["status"] == "VALID"), key=lambda o: (o["origin"] != "cron", o["actual_run_time"])):
        if o["slot"] in reps:
            first = reps[o["slot"]]
            o["status"], o["basis"] = "DUPLICATE_EXCLUDED", f"슬롯 {o['slot']}는 {first['origin']} {first['actual_run_time']}가 대표"
        else:
            o["basis"] = "cron 우선" if o["origin"] == "cron" else "이 슬롯의 유일한·가장 이른 동등 실행"
            reps[o["slot"]] = o
    st = collections.Counter(o["status"] for o in obs)
    rep = list(reps.values())
    return dict(valid_cron=sum(o["origin"] == "cron" for o in rep), valid_approved_manual=sum(o["origin"] == "manual" for o in rep),
                valid_production_equivalent_total=len(rep), skipped=st["SKIPPED"], duplicate_excluded=st["DUPLICATE_EXCLUDED"],
                invalid=st["INVALID"] + st["EXCLUDED_UNAPPROVED"] + st["EXCLUDED_NOT_EQUIVALENT"], rehearsal_or_dry_run=st["EXCLUDED_REHEARSAL"],
                progress=f"{len(rep)}/{SLOTC_TARGET}", observations=obs, representatives=rep)

def slot_c_run(today=None, live=None, log=print, write=True, before=None, ab_files=None, run_source="manual", manual_meta=None):
    """원고 작업 뒤 실행. 큐 스냅샷(history 최신)을 읽어 C를 고르고 slot_c_shadow.tsv·slot_c_report.md만 쓴다. 실패하면 기록만 빠진다.
    A/B(Phase 6.1): 이번 실행이 새로 만든 일반 원고 — before(실행 전 파일 목록)와 지금 목록의 차이가 정확히 2편일 때만. 아니면 추측하지 않고
    SKIPPED(ambiguous_ab)로 남긴다. 수동 실행은 ab_files로 두 원고를 직접 준다(run_source=manual). 같은 날 이미 유효한 기록이 있으면 SKIPPED로 덮지 않는다.
    manual_meta(2026-10-09): 승인 수동 실행이면 공식 TSV(날짜당 cron 한 줄)는 건드리지 않고 SLOTC_MANUAL_F에 실행 시각 단위로 남긴다.
    선정 방법은 같다 — 기록 위치만 다르다."""
    try:
        day = today or f"{now():%Y-%m-%d}"
        hist = sorted(glob.glob(os.path.join(KW_DIR, "history", "*.json")))
        cands = json.load(io.open(hist[-1], encoding="utf-8")).get("candidates", []) if hist else []
        for c in cands:
            c["src"] = set(c.get("src") or ())
        posts = own_posts() if live is None else [dict(p, live=False) for p in _own_posts_nolive()]
        by_file = {p["file"]: p for p in posts}
        skip, ab_files_ = None, None
        if ab_files:
            ab_files_, src = [os.path.relpath(f, VAULT) if os.path.isabs(f) else f for f in ab_files], "수동 지정(--ab)"   # 볼트 상대 경로나 절대 경로
        elif before is None:
            skip = "no_snapshot"
        else:
            new = sorted(set(general_article_files()) - set(before))
            ab_files_, src = new, f"이번 실행 새 원고 {len(new)}편"
            if len(new) != 2:
                skip = f"ambiguous_ab(new={len(new)})"
        ab_posts = []
        if not skip:
            ab_posts = [by_file.get(f) for f in sorted(ab_files_)]
            if len(ab_posts) != 2 or not all(p and p["keywords"] for p in ab_posts):
                skip = "ambiguous_ab(키워드를 읽지 못한 원고)"
        rec = {k: "" for k in SLOTC_COLS}
        rec.update(date=day, run_source=run_source)
        best = second = None
        rows, expansion = [], []
        if skip:
            rec.update(ab_source=f"SKIPPED: {skip}", selection_reason="A/B를 확실히 알 수 없어 Slot C를 고르지 않았다(A/B 원고·큐·발행과 무관)")
        else:
            ab_kws = [p["keywords"][0] for p in ab_posts]
            tx = taxonomy_corpus(live)
            rec_kws = [p["keywords"][0] for p in recent_posts(posts, 7, day) if p["keywords"] and p not in ab_posts]
            best, second, rows, expansion = select_slot_c(cands, ab_kws, tx, rec_kws, posts, day)
            rec.update(slot_a=ab_kws[0], slot_b=ab_kws[1], ab_source=src,
                       a_article_id=os.path.basename(ab_posts[0]["file"])[:-3], b_article_id=os.path.basename(ab_posts[1]["file"])[:-3])
        if best:
            d = best["d"]
            rec.update(keyword=best["kw"], lane=d["lane"], cluster=d["cluster"], facet=best["facet"], intent=d["intent"], entity=",".join(d["entity"]),
                       demand=d["demand"], priority_score=str(best["score"]), decision=d["decision"], cluster_status=d["cluster_status"],
                       internal_link_opportunities=";".join(f"{x['target'][:20]}(P{x['relationship']['priority']})" for x in best["links"]),
                       content_gap="yes" if best["gap"] else "no", diversity_reason=" / ".join(best["div"]) or "A/B와 겹침 낮음",
                       selection_reason=_slotc_reason(best), shadow_score=str(best["shadow"]),
                       temporal_status=best["temporal"]["status"], target_period=best["temporal"]["target_period"])
        if second:
            rec.update(runner_up=second["kw"], runner_up_reason=f"그림자 점수 {second['shadow']} < {best['shadow']} — " + _slotc_reason(second)[:120])
        if write and manual_meta is not None:
            rec.update(run_source="manual", **{k: manual_meta.get(k, "") for k in SLOTC_MANUAL_EXTRA})
            rec["production_slot"] = rec["production_slot"] or _production_slot(rec)
            rec["equivalence"] = rec["equivalence"] or "PENDING"
            keep = {r["actual_run_time"]: r for r in _read_slotc_manual()}
            keep[rec["actual_run_time"]] = rec
            _write_slotc_manual(list(keep.values()))
            write_slot_c_report(rec, second, rows, expansion, best)
        elif write:
            keep = {r["date"]: r for r in _read_slotc()}
            old = keep.get(day)
            if skip and old and not _skipped(old):
                log(f"· Slot C 그림자 생략: {skip} — 같은 날 유효한 기록이 이미 있어 덮지 않는다")
                return rec
            if old:     # 같은 날 다시 돌려도 사람이 적은 manual 칸은 지키고 나머지만 갈아 끼운다
                rec["manual"], rec["manual_note"] = old["manual"], old["manual_note"]
            keep[day] = rec
            _write_slotc(list(keep.values()))
            write_slot_c_report(rec, second, rows, expansion, best)
        log(f"· Slot C 그림자: {rec['keyword'] or ('SKIPPED ' + skip if skip else '선정 없음')} (A/B: {rec['slot_a'] or '—'}, {rec['slot_b'] or '—'}) → {os.path.basename(SLOTC_F)}")
        return rec
    except Exception as e:
        import traceback
        log(f"  ! Slot C 그림자 생략(A/B와 무관): {type(e).__name__}: {e}")
        traceback.print_exc()
        return None

def _own_posts_nolive():
    global _LIVE
    keep, _LIVE = _LIVE, {}
    try:
        return own_posts()
    finally:
        _LIVE = keep

def write_slot_c_report(rec, second, rows, expansion, best=None):
    L = [f"# Slot C 그림자 — {rec['date']}", "", "> 세 번째 글을 쓴다면 무엇을 쓸지 고른 기록이다. 실제 글은 만들지 않는다(하루 발행은 2편 그대로).", "",
         f"- A/B: {rec['slot_a'] or '—'} / {rec['slot_b'] or '—'} ({rec['ab_source']}) · 원고 {rec['a_article_id'] or '—'} / {rec['b_article_id'] or '—'} · 실행 {rec['run_source']}"
         + (f" ({rec.get('execution_type')} {rec.get('actual_run_time')} · 동등성 {rec.get('equivalence')})" if rec.get("execution_type") else "")]
    ev = slot_c_eval()
    L += [f"- 공식 평가 진행률 {ev['progress']} (cron {ev['valid_cron']} · 승인 수동 {ev['valid_approved_manual']} · SKIPPED {ev['skipped']}"
          f" · 중복 제외 {ev['duplicate_excluded']}) — slot_c_stats와 같은 집계"]
    if rec["keyword"]:
        L += ["", f"**후보: {rec['keyword']}**", "", "이유:"] + [f"- {x}" for x in rec["selection_reason"].split(" · ")]
        if best:
            t = best["temporal"]
            L += ["", f"시간: {t['status']} · 대상 기간 {t['target_period'] or '—'} · 표현 {', '.join(t['expressions']) or '없음'}"
                  + (f" · 연도만 다른 기존 글(YEAR_VARIANT, 중복 아님): {', '.join(best['year_variants'])}" if best["year_variants"] else ""),
                  "", "점수 내역: " + " · ".join(f"{k} {v:+}" for k, v in best["adj"].items()) + f" = {best['shadow']}"]
        L += ["", f"내부 링크: {rec['internal_link_opportunities'] or '현재 없음'}", "", f"차점: {rec['runner_up'] or '—'}" + (f" — {rec['runner_up_reason']}" if rec["runner_up"] else "")]
    elif _skipped(rec):
        L += ["", f"**{rec['ab_source']}** — {rec['selection_reason']}"]
    else:
        L += ["", "**후보 없음** — 조건을 채우는 큐 후보가 없다"]
    outs = collections.Counter(r["out"].split("(")[0].split(" —")[0] for r in rows if "out" in r)
    L += ["", "## 제외 사유", ""] + ([f"- {k}: {v}" for k, v in outs.most_common()] or ["- 없음"])
    L += ["", "## cluster_expansion_candidates (레지스트리는 고치지 않는다)", ""] + ([f"- {e['keyword']} — {e['kind']} · 수요 {e['demand']}" for e in expansion] or ["- 없음"])
    io.open(SLOTC_REPORT_F, "w", encoding="utf-8").write("\n".join(L) + "\n")

def slot_c_stats(path=None, manual_path=None):
    """그림자 기록의 품질 지표. 14회 평가 표본은 slot_c_eval의 생산 동등 대표 관찰이다(2026-10-09 Thomas: cron·승인 수동 같은 자격,
    같은 생산 슬롯은 하나). 10-07 수동 리허설은 빠진다. 지표(ACTIVE·CONFIRMED…)도 그 대표 관찰로 계산한다."""
    R, ev = _read_slotc(path), slot_c_eval(path, manual_path)
    valid = ev["representatives"]
    n = len(valid) or 1
    pct = lambda k: f"{100 * k / n:.0f}%" if valid else "—"
    cnt = lambda f: sum(1 for r in valid if f(r))
    return dict(total=len(R), valid_cron=ev["valid_cron"], valid_approved_manual=ev["valid_approved_manual"],
                valid_production_equivalent_total=ev["valid_production_equivalent_total"], progress=ev["progress"],
                skipped=ev["skipped"], invalid=ev["invalid"], duplicate_excluded=ev["duplicate_excluded"], rehearsal_or_dry_run=ev["rehearsal_or_dry_run"],
                manual_or_rehearsal=sum(1 for r in R if r["run_source"] != "cron"),
                representatives=[f"{o['slot']} ← {o['origin']} {o['actual_run_time']} · {o['keyword']} ({o['basis']})" for o in valid],
                excluded=[f"{o['origin']} {o['actual_run_time']} → {o['status']}" + (f" ({o['basis']})" if o.get("basis") else "")
                          for o in ev["observations"] if o["status"] != "VALID"],
                active=pct(cnt(lambda r: r["cluster_status"] == "ACTIVE")), candidate=pct(cnt(lambda r: r["cluster_status"] == "CANDIDATE")),
                unresolved=pct(cnt(lambda r: r["cluster"] == "unresolved")), confirmed=pct(cnt(lambda r: r["demand"] == "CONFIRMED")),
                temporal={t: pct(cnt(lambda r, t=t: r["temporal_status"] == t)) for t in ("CURRENT_PERIOD", "UPCOMING_PERIOD", "EXPIRED_PERIOD", "TIMELESS", "AMBIGUOUS")},
                same_cluster_same_facet=cnt(lambda r: DIV_SAME_FACET in r["diversity_reason"]),
                same_cluster_distinct_facet=cnt(lambda r: DIV_DISTINCT_FACET in r["diversity_reason"]),
                link_p1p2=pct(cnt(lambda r: bool(r["internal_link_opportunities"]))), content_gap=pct(cnt(lambda r: r["content_gap"] == "yes")),
                manual=dict(collections.Counter(r["manual"] or "(미평가)" for r in valid)))

OOL_DAYS = 7   # (나) 2026-10-21: 체급 밖 측정을 다시 쓰는 기간(일). 되돌리기 = 0


def out_of_league_serp(m):
    """도달 게이트에 걸리는 SERP 측정인가(run의 reachable과 같은 기준). 못 읽은 측정은 체급 밖이 아니다."""
    return bool(m) and m.get("auth_med") is not None and (m["auth_med"] > AUTH_CAP or (m.get("exact10") or 0) > EXACT_CAP)


def known_out_of_league(days=OOL_DAYS, today=None):
    """최근 days일 안에 '체급 밖'으로 잰 말 → {정규화: {"serp", "date"}}. 날짜는 SERP를 실제로 잰 날(serp_date)이다 —
    건너뛴 말을 다시 저장해도 측정일이 그대로라 days가 지나면 다시 잰다. history 스냅샷의 out_of_league(2026-10-21부터 저장)만 읽는다."""
    if days <= 0:
        return {}
    lo = ((today or now().date()) - datetime.timedelta(days=days)).isoformat()
    out = {}
    for h in sorted(glob.glob(os.path.join(KW_DIR, "history", "*.json"))):
        try:
            rows = json.load(io.open(h, encoding="utf-8")).get("out_of_league", [])
        except Exception:
            continue
        for r in rows:
            d, m = str(r.get("serp_date") or ""), r.get("serp")
            if d >= lo and out_of_league_serp(m):
                out[norm(r.get("kw", ""))] = {"serp": m, "date": d}
    return out


POOL_DAYS, POOL_PER_LANE = 14, 10   # 후보 풀 창·레인별 상한(2026-10-20). 되돌리기 = POOL_PER_LANE 0


def pool_candidates(have, posts, days=POOL_DAYS, per=POOL_PER_LANE, today=None):
    """최근 days일 history 후보 중 오늘 발굴(have, 정규화)에 없고 지금도 레인·의도·보유 거르기를 통과하는 것 → run의 새 후보(출처 '풀').
    레인마다 마지막으로 잡힌 날의 점수 순 per개(점수는 순서만 정한다 — 검색량·경쟁도는 run이 다시 잰다). 레인은 오늘 lane_of로만 본다(씨앗 레인 예외 없음). 장비 레인은 제휴 재고
    (affiliate_stock.json)가 이미 history를 합쳐 쌓으므로 넣지 않는다. 어떤 오류든 빈 목록 — 오늘 발굴만으로 큐를 만든다."""
    if per <= 0:
        return []
    try:
        lo = ((today or now().date()) - datetime.timedelta(days=days)).isoformat()
        last = {}
        for h in sorted(glob.glob(os.path.join(KW_DIR, "history", "*.json"))):
            if os.path.basename(h)[:10] < lo:
                continue
            try:
                cs = json.load(io.open(h, encoding="utf-8")).get("candidates", [])
            except Exception:
                continue   # 깨진 사본 하나로 풀 전체를 버리지 않는다
            for c in cs:
                n = norm(c.get("kw", ""))
                if n:
                    last[n] = c   # 날짜 순이라 마지막으로 잡힌 기록이 남는다
        by_lane = {}
        for n, c in last.items():
            kw = c["kw"]
            lane = lane_of(kw)
            if n in have or not lane or lane == "장비" or intent_of(kw) not in ("사장님", "양쪽") or covered_by(kw, posts):
                continue
            by_lane.setdefault(lane, []).append((-(c.get("score") or 0), kw, set(c.get("src") or ())))
        # 원래 출처(유입·연관)는 남긴다 — 판정 단계의 수요 근거가 출처를 본다(demand_evidence)
        return [{"kw": kw, "lane": lane, "src": src | {"풀"}, "pos": 9, "nav": False, "goo": False, "intent": intent_of(kw)}
                for lane, xs in by_lane.items() for _, kw, src in sorted(xs, key=lambda x: x[:2])[:per]]
    except Exception as e:
        print(f"  ! 후보 풀 실패 — 오늘 발굴만 쓴다: {type(e).__name__}: {e}")
        return []


def stale_candidates(posts):
    """마지막 큐의 후보 중 그 뒤에 쓴 원고가 이미 다룬 것. 2026-09-22 큐의 후보 29개 중 9개가 41~51편으로 쓰였는데
    --max-age 7이 그 큐를 그대로 재사용했다. 파일 mtime은 쓰지 않는다 — git pull·backlinked 기입만으로도 바뀐다."""
    hist = sorted(glob.glob(os.path.join(KW_DIR, "history", "*.json")))
    try:
        cands = json.load(io.open(hist[-1], encoding="utf-8")).get("candidates", []) if hist else []
    except Exception:
        return []
    rej = naver_rejects()   # 2026-10-25: STEP 0이 버린 후보가 큐에 남아 있으면 큐를 새로 만든다
    return [c["kw"] for c in cands if covered_by(c["kw"], posts) or norm(c["kw"]) in rej]


# ───────────────────────── 순위 추적 ─────────────────────────
def rank_track(posts, log=print):
    rows = []
    pub = [p for p in posts if p["platform"] == "naver" and is_published(p) and p["keywords"]]
    log(f"· 내 글 순위 추적 {len(pub)}편")
    prev = {}
    hist = sorted(glob.glob(os.path.join(KW_DIR, "history", "*.json")))
    today_f = os.path.join(KW_DIR, "history", f"{now():%Y-%m-%d}.json")
    hist = [h for h in hist if h != today_f]
    if hist:
        try:
            prev = {(r["file"], r["kw"]): r["rank"] for r in json.load(io.open(hist[-1], encoding="utf-8")).get("ranks", [])}
        except Exception:
            prev = {}
    for p in pub:
        for kw in p["keywords"][:2]:
            rs = serp(kw)
            rank = next((r["rank"] for r in rs if r["blog"] == MY_BLOG), None)
            title = p.get("live_title") or p["title"]      # 제목 일치는 볼트가 아니라 발행 제목으로 본다
            rows.append({"file": p["file"], "kw": kw, "rank": rank, "prev": prev.get((p["file"], kw)), "had_prev": (p["file"], kw) in prev,
                         "in_title": norm(kw) in norm(title), "title": title, "published": p["published"],
                         "title_diff": bool(p.get("live_title")) and norm(p["live_title"]) != norm(p["title"]),
                         "parsed": bool(rs)})
    return rows


# ───────────────────────── 출력 ─────────────────────────
def fmt_vol(c, has_vol):
    if not has_vol:
        return "—"
    v = c.get("vol") or {}
    return f"{v.get('total', 0):,}" if v else "0"

def write_queue(short, variants, ranks, dropped, has_vol, parser_broken=False, out_of_league=(), ref=None, posts=None, tistory=()):
    """표가 아니라 목록으로 쓴다 — 서버가 다시 쓰는 파일의 표를 맥 Obsidian이 자동 정렬하면 Git 충돌이 난다(2026-09-16 사고)."""
    t = now()
    # 2026-10-02: 이번 실행의 스냅샷을 먼저 남긴다 — 장비 절은 그 스냅샷까지 합친 제휴 재고에서 그린다
    snap = {"date": f"{t:%Y-%m-%d}", "has_vol": has_vol,
            "candidates": [{k: (sorted(v) if isinstance(v, set) else v) for k, v in c.items()} for c in short],
            "tistory": [{k: (sorted(v) if isinstance(v, set) else v) for k, v in c.items()} for c in tistory],
            # 2026-10-21 (나): 체급 밖으로 내린 말과 측정일 — 다음 실행이 OOL_DAYS일 동안 SERP를 건너뛴다(known_out_of_league)
            "out_of_league": [{"kw": c["kw"], "lane": c.get("lane"), "vol": c.get("vol"), "serp": c.get("serp"), "serp_date": c.get("serp_date")}
                              for c in out_of_league],
            "ranks": ranks}
    os.makedirs(os.path.join(KW_DIR, "history"), exist_ok=True)
    json.dump(snap, io.open(os.path.join(KW_DIR, "history", f"{t:%Y-%m-%d}.json"), "w", encoding="utf-8"), ensure_ascii=False, indent=1)
    stock = update_stock(posts, log=lambda *a: None)
    L = [f"# 키워드 큐 — {t:%Y-%m-%d}", "",
         "> `tools/kw_pipeline.py run` 이 만든 파일이다. 손으로 고치지 않는다(다음 실행 때 덮어쓴다).",
         "> 씨앗어·채널·시즌 달력은 같은 폴더의 `seeds.txt` · `channels.txt` · `calendar.tsv` 에서 고친다. `seeds_trend.txt`(출처 '트렌드')는 맥이 매일 덮어쓴다.",
         f"> 수요 데이터: **{'네이버 검색광고 API 월 검색량(PC+모바일)' if has_vol else '검색광고 API 미연동 — 점수는 자동완성 기반 대리 신호다. 검색량이 아니다'}**",
         "> 읽는 법: `경쟁 a/b/c` = 블로그탭 상위 10의 (추정 일방문 중앙값 / 같은 검색어를 노린 제목 수(어순 무시) / 30일 이내 글 수). "
         f"내 글 31개 실측 기준 **a가 120 이하이고 b가 4 이하면 3위 안 88%**다. a가 {AUTH_CAP} 초과이거나 b가 {EXACT_CAP + 1}/10이면 "
         "아래 '체급 밖'으로 내린다. `도달`은 a·b를 0~1로 합친 값, `AC` = 네이버·구글 자동완성.", ""]
    # 2026-09-27: 하루 2편이면 한 주에 새 주제 14개가 필요하다. 3위 안 88% 구간(a≤120·b≤4) 후보가 그보다 적으면
    # 씨앗어를 늘려야 한다는 신호다 — 주간 분석이 이 줄을 보고 결정한다
    need = GEN_PER_DAY * 7
    easy = [c for c in short if (c.get("serp") or {}).get("auth_med") is not None
            and c["serp"]["auth_med"] <= 120 and (c["serp"].get("exact10") or 0) <= 4]
    L += [f"> 공급: 한 주 필요 **{need}편**(원고 생성 하루 {GEN_PER_DAY}편 · 발행 하루 {POSTS_PER_DAY}편) · 새 후보 {len(short)}개 중 3위 안 88% 구간(a≤120·b≤4) **{len(easy)}개**"
          + (" — ⚠️ 필요 편수보다 적다. `seeds.txt`에 씨앗어를 더하거나 보유 글 보강(아래 '보유 변형')으로 채운다" if len(easy) < need else ""), ""]
    fr = gsc_freshness()
    if fr.startswith("⚠"):
        L += ["> " + fr, ""]          # G3
    if parser_broken:
        L += ["> ⚠️ **SERP 파서 점검 필요** — 절반 이상의 키워드에서 검색 결과를 못 읽었다. 네이버 검색 화면 구조가 바뀐 듯하다(`parse_serp`).", ""]
    season = [c for c in short if c.get("season")] + [c for c in variants if c.get("season")]
    if season:
        when = f"예상 발행일 {ref[0]:%m-%d} 기준(네이버 대기 {ref[1]}편 · 하루 {POSTS_PER_DAY}편)" if ref else "오늘 기준"
        L += [f"## 시즌 임박 — 정점 1~3주 전 발행이 목표 · D-는 {when}", ""]
        groups = {}
        for c in season:
            groups.setdefault(c["season"][1] or "시즌", []).append(c)
        vol = lambda c: (c.get("vol") or {}).get("total", 0)
        for ev, cs in sorted(groups.items(), key=lambda kv: min(c["season"][0] for c in kv[1])):
            new = sorted([c for c in cs if "score" in c], key=lambda c: -c["score"])
            old = sorted([c for c in cs if "covered" in c], key=lambda c: -vol(c))
            bits = []
            if new:
                bits.append("새 후보 " + ", ".join(f"**{c['kw']}**(점수 {c['score']})" for c in new[:3]))
            if old:
                files = sorted({os.path.basename(c["covered"][0])[:22] for c in old})
                bits.append(f"보유 글 {', '.join(files)} — 변형 {len(old)}개는 보강·후속편으로"
                            f"({', '.join(c['kw'] for c in old[:3])}{' …' if len(old) > 3 else ''})")
            L.append(f"- **{ev}** — D-{min(c['season'][0] for c in cs)} · " + " · ".join(bits))
        L.append("")
    for lane in LANES:
        if lane == "장비":
            L += stock_section(stock)
            continue
        rows = [c for c in short if c["lane"] == lane][:15]
        if not rows:
            continue
        L += [f"## {lane} — " + ("제휴 글 후보 (blog-variety --report가 '제휴 차례'일 때만 쓴다)" if lane == "장비" else "다음 편 후보"), ""]
        for i, c in enumerate(rows, 1):
            m = c.get("serp") or {}
            comp = f"{m.get('auth_med', '?')}/{m.get('exact10', '?')}/{m.get('fresh30', '?')}" if m else "미조사"
            bits = [f"점수 {c['score']}"]
            if has_vol:
                bits.append(f"월 {fmt_vol(c, has_vol)}회")
            bits += [f"경쟁 {comp}", f"도달 {attain(m)}", f"AC {c.get('nav_v', '?')}·{c.get('goo_v', '?')}", c["intent"]]
            if form_hint(c["kw"]):
                bits.append(form_hint(c["kw"]))
            if c.get("niche"):
                bits.append("틈새: " + ", ".join(c["niche"]))
            bits.append("출처 " + "·".join(sorted(c["src"])))
            if m.get("my_rank"):
                bits.append(f"내 글 {m['my_rank']}위")
            bits.append(slot_txt(c["kw"]))   # 티스토리 판을 만들지 정하는 값(naver-to-google-seo 1-A 4)
            if decision_tag(c):
                bits.append(decision_tag(c))   # 2026-10-08 판정·클러스터·수요(근거) — 자세한 것은 decision_report.md
            L.append(f"{i}. **{c['kw']}**{' 🗓' if c.get('season') else ''} — " + " · ".join(bits))
        L.append("")
    if tistory:
        # 2026-10-03: 변환을 건너뛴 날 티스토리 슬롯을 채우는 후보. '자리 있음'만 쓴다 — 미측정은 크롬 측정(절차 8절)이 먼저 잰다
        opened = [c for c in tistory if (slot_of(c["kw"]) or {}).get("open")]
        pending = [c for c in tistory if not slot_of(c["kw"])]
        closed = [c for c in tistory if slot_of(c["kw"]) and not slot_of(c["kw"])["open"]]
        L += ["## 티스토리 전용 — 구글에 블로그 자리가 있는 AI 도구 의도 (변환을 건너뛴 슬롯용)", "",
              "> 도구명 + 요금제·무료 한도·해지·환불·오류·비교. 네이버 원본 없이 티스토리에만 쓴다(naver-to-google-seo '티스토리 전용 글'). "
              f"**고를 때는 `kw_pipeline.py tistory-pick`(지금 측정값)을 쓴다 — 이 목록은 큐를 만든 날 값이다.** 자리 있음 {len(opened)} · 측정 대기 {len(pending)} · 자리 없음 {len(closed)}", ""]
        for i, c in enumerate(opened[:15], 1):
            L.append(f"{i}. **{c['kw']}** — 월 {fmt_vol(c, has_vol)}회 · {slot_txt(c['kw'])}" + (f" · {form_hint(c['kw'])}" if form_hint(c["kw"]) else ""))
        if pending:
            L.append("- 측정 대기: " + ", ".join(f"{c['kw']}({fmt_vol(c, has_vol)})" for c in pending[:15]) + (" …" if len(pending) > 15 else ""))
        if closed:
            L.append("- 자리 없음(쓰지 않는다): " + ", ".join(c["kw"] for c in closed[:10]) + (" …" if len(closed) > 10 else ""))
        L.append("")
    if ranks:
        unparsed = sum(not r["parsed"] for r in ranks)
        ok = [r for r in ranks if r["rank"]]
        L += ["## 내 글 순위 (네이버 블로그탭, 메인·보조 키워드)", "",
              f"3위 안 {sum(r['rank'] <= 3 for r in ok)} · 10위 안 {sum(r['rank'] <= 10 for r in ok)} · 30위 밖 {len(ranks) - len(ok)} (전체 {len(ranks)})"
              + (f" · 검색 결과를 못 읽은 키워드 {unparsed}" if unparsed else ""),
              "형식: 순위(지난번) · 키워드 · 제목에 정확 일치 여부(발행 제목 기준 — 네이버 RSS) · 글", ""]
        for r in sorted(ranks, key=lambda r: (r["rank"] or 99, r["kw"])):
            prev = "" if not r.get("had_prev") else f"(지난번 {r['prev'] or '30위 밖'})"
            flag = ""
            if r.get("had_prev") and r["prev"] and r["prev"] <= 10 and (not r["rank"] or r["rank"] > 10):
                flag = " ⬇ 10위 밖으로"
            diff = " (발행 제목≠볼트 제목)" if r.get("title_diff") else ""
            L.append(f"- {str(r['rank']) + '위' if r['rank'] else '30위 밖'}{prev}{flag} · {r['kw']} · 제목 {'O' if r['in_title'] else 'X'}{diff} · {os.path.basename(r['file'])[:26]}")
        L.append("")
    if out_of_league:
        L += ["## 참고: 지금 체급 밖 — 검색량은 크지만 상위가 굳어 있다", "",
              f"상위 10의 추정 일방문 중앙값이 {AUTH_CAP} 초과이거나 제목 정확 일치가 {EXACT_CAP}개 초과인 칸이다. "
              "쓰지 말라는 뜻이 아니라, 이 키워드를 제목에 걸어도 지금은 검색 유입이 거의 안 붙는다는 뜻이다. "
              "블로그가 커지면 다시 본다.", ""]
        for c in out_of_league[:10]:
            m = c.get("serp") or {}
            L.append(f"- {c['kw']} — 월 {fmt_vol(c, has_vol)}회 · 경쟁 {m.get('auth_med')}/{m.get('exact10')}/{m.get('fresh30')}")
        L.append("")
    if variants:
        L += ["## 보유 키워드의 변형 — 새 글이 아니라 후속편·보강·역링크 후보", ""]
        vs = sorted(variants, key=lambda c: (-(c.get("vol") or {}).get("total", 0), c["pos"]))[:30]
        for c in vs:
            L.append(f"- {c['kw']}{' (월 ' + fmt_vol(c, has_vol) + '회)' if has_vol else ''} ← {os.path.basename(c['covered'][0])[:26]} ({c['covered'][1]})")
        L.append("")
    L += ["## 제외 집계", "", ", ".join(f"{k} {v}" for k, v in dropped.items()) or "없음", ""]
    io.open(os.path.join(KW_DIR, "queue.md"), "w", encoding="utf-8").write("\n".join(L))


